#!/usr/bin/env python3
"""Project Necrozma — single-file bundle (generated by bundle.py; do not hand-edit).

Runs a live paper-trading tick with no repo on disk. State is read from and
written to ./live_state.json so it can be round-tripped through storage.

    python evotrader_bundle.py tick             # one tick, real prices
    python evotrader_bundle.py summary          # account status, no trading
    python evotrader_bundle.py evolve N         # N generations of self-improvement
    python evotrader_bundle.py signals          # today's decision in plain language
    python evotrader_bundle.py anatomy          # P&L post-mortem on every closed trade
    python evotrader_bundle.py consults         # are the three consults actually independent?
    python evotrader_bundle.py review-hard-calls  # list/record verdicts on flagged bars
    python evotrader_bundle.py fold-scheme      # fold-count sensitivity of fold-aggregate fitness
    python evotrader_bundle.py fitness-decomp   # split aggregate_fitness into mean vs consistency-penalty term
    python evotrader_bundle.py regime-scan      # is the fold-2 melt-up concentrated enough to warrant regime-stratified folds?
    python evotrader_bundle.py regime-folds     # does grouping sub-windows by regime instead of calendar stabilize aggregate_fitness?
    python evotrader_bundle.py fold-cap         # does winsorizing the outlier fold's pull on the mean term stabilize aggregate_fitness?
    python evotrader_bundle.py margin-curve     # how much does required_margin() actually grow with n_candidates/n_draws?
"""
import sys, types, json, os, math

_SRC = {}
_SRC['constitution'] = '"""THE CONSTITUTION — locked.\n\nEverything in this package defines how the system is *graded*. The Researcher\nmay propose any change to the strategy layer; it may not propose a change to\nanything in here. The Superior Judge verifies the checksum of this package at\nstartup and refuses to run if it moved without a human editing MANIFEST.\n\nWhy this exists: a self-modifying system whose reward function is inside its\nown mutable surface will always find it cheaper to edit the scoreboard than to\nlearn the game. Locking the scoreboard is what makes the rest safe to leave\nrunning unattended.\n\nOnly Burk edits this file, by hand.\n"""\nfrom __future__ import annotations\n\nimport hashlib\nimport math\nimport os\nfrom typing import Any\n\n# ---------------------------------------------------------------------------\n# Fitness\n# ---------------------------------------------------------------------------\n\nMIN_TRADES = 30\nMIN_BARS = 90\nMAX_DD_HARD_FAIL = 0.40\nDD_FREE_ALLOWANCE = 0.20\nDD_PENALTY_WEIGHT = 2.0\nTURNOVER_FREE = 50.0\nTURNOVER_PENALTY_WEIGHT = 0.5\n\n# Acceptance gates\nDD_REGRESSION_TOLERANCE = 1.15     # challenger maxDD may be at most 15% worse\nCOMPLEXITY_COST_PER_UNIT = 0.05    # fitness margin required per unit of added complexity\nMULTIPLE_TESTING_SIGMA = 0.08      # noise scale of a fold-aggregate fitness estimate\nHOLDOUT_SIGMA = 2.0                # noise scale of a single sealed-holdout fitness estimate.\n                                   # Calibrated 2026-08-21 from `holdout-noise`\'s block-bootstrap\n                                   # measurement of the real sealed-holdout return path across all\n                                   # three real champions this account has had (boot_fitness_std in\n                                   # fitness units: v1 ~1.48, v2 ~1.21, v3 ~2.04). Set at the highest\n                                   # observed, not an average -- this is a safety floor and future\n                                   # champions are unmeasured. holdout_accepts()\'s own docstring\n                                   # already argued a single holdout window is noisier than a\n                                   # fold-aggregate; this is that argument with a number attached,\n                                   # not a guess. Still likely an underestimate: it measures\n                                   # realized-path resampling noise only, not the extra noise from\n                                   # candidates arriving pre-selected by folds that correlate with\n                                   # the holdout window. See AMENDMENTS.md.\nCIRCUIT_BREAKER_DD = 0.25\nCIRCUIT_BREAKER_COOLDOWN = 20      # bars frozen after a trip\nCIRCUIT_BREAKER_FLATTEN = True     # liquidate on trip, don\'t hold bags through a crash\n\n# Evolution search hygiene\nHOLDOUT_FRAC = 0.15                # newest slice of history, never touched during search\nN_FOLDS = 3                        # walk-forward folds used to judge a challenger\nFOLD_CONSISTENCY_WEIGHT = 0.35     # penalty on cross-fold variance: a strategy that\n                                   # works in one fold and dies in another is not a strategy\n\n\ndef fitness(stats: dict[str, Any]) -> float:\n    """The single number the whole evolution loop optimises.\n\n    Deliberately NOT total return. Return alone rewards leverage, luck and\n    catastrophic risk-taking; over a long enough run those all end at zero.\n    """\n    if stats.get("error"):\n        return float("-inf")\n    if stats.get("trades", 0) < MIN_TRADES:\n        return float("-inf")\n    if stats.get("bars", 0) < MIN_BARS:\n        return float("-inf")\n    max_dd = abs(stats.get("max_dd", 0.0))\n    if max_dd > MAX_DD_HARD_FAIL:\n        return float("-inf")\n\n    base = stats.get("sortino", 0.0)\n    if not math.isfinite(base):\n        base = 0.0\n    dd_pen = DD_PENALTY_WEIGHT * max(0.0, max_dd - DD_FREE_ALLOWANCE)\n    turn = stats.get("turnover_annual", 0.0)\n    turn_pen = TURNOVER_PENALTY_WEIGHT * max(0.0, (turn - TURNOVER_FREE) / TURNOVER_FREE)\n    return float(base - dd_pen - turn_pen)\n\n\nRANK_FLOOR = -5.0\n\n\ndef ranking_fitness(stats: dict[str, Any]) -> float:\n    """Fitness with a finite floor, for *ranking* candidates during search.\n\n    `fitness()` returns -inf for anything that fails a hard gate, which is the\n    correct verdict but destroys the gradient: if every candidate scores -inf\n    the search is blind. Ranking uses a floor so search can still climb toward\n    the gates; acceptance still uses the real `fitness()`, so a floored score\n    can never buy a promotion.\n    """\n    f = fitness(stats)\n    return RANK_FLOOR if f == float("-inf") else max(f, RANK_FLOOR)\n\n\ndef required_margin(n_candidates: int, complexity_delta: int,\n                    sigma: float = MULTIPLE_TESTING_SIGMA) -> float:\n    """How much better a challenger must be before we believe it.\n\n    Test k noisy candidates and pick the winner, and it beats the truth by\n    roughly sigma * sqrt(2 * ln k) on luck alone. That is the shape of the\n    penalty — NOT linear in k.\n\n    (v0.1 had this linear at 0.02/candidate, which set the bar at 0.46 for a\n    24-candidate generation and made promotion arithmetically impossible on a\n    Sortino-scaled metric. That was a mis-specification, not a safety property.\n    The sqrt-log form is the standard correction for the expected maximum of k\n    noisy estimates. The real defences against crowning noise — the cross-fold\n    consistency penalty and the sealed holdout — are unchanged.)\n\n    `sigma` defaults to `MULTIPLE_TESTING_SIGMA`, the fold-aggregate noise\n    scale — that is the right constant for `accepts()`, which mines the\n    fold-aggregate metric. `holdout_accepts()` passes `HOLDOUT_SIGMA` instead:\n    a single sealed-holdout score is a noisier estimate than a fold-aggregate\n    (fewer effective independent windows averaged), so the same k-candidate\n    correction needs a larger sigma to mean the same thing.\n    """\n    mt = sigma * math.sqrt(2.0 * math.log(max(n_candidates, 2)))\n    cx = COMPLEXITY_COST_PER_UNIT * max(0, complexity_delta)\n    return mt + cx\n\n\ndef accepts(champion: dict[str, Any], challenger: dict[str, Any],\n            n_candidates: int = 1, complexity_delta: int = 0,\n            champion_score: float | None = None,\n            challenger_score: float | None = None) -> tuple[bool, str]:\n    """The acceptance rule. Returns (accept?, human-readable reason).\n\n    `champion_score` / `challenger_score` are the **selection metric** — the\n    fold-aggregate fitness that actually ranked the candidates. The margin is\n    applied there, because that is where selection bias enters. `champion` and\n    `challenger` are the merged fold stats, used for the hard gates and the\n    drawdown-regression check.\n\n    (Earlier this applied the multiple-testing margin to the merged stats,\n    which rank nothing, while the fold-aggregate that does the ranking got no\n    protection at all. Backwards on both counts: the metric being mined for a\n    winner is the one that needs the correction. Falling back to the merged\n    fitness when no score is supplied keeps the old call sites honest.)\n    """\n    f_champ = fitness(champion)\n    f_chal = fitness(challenger)\n\n    if f_chal == float("-inf"):\n        return False, "challenger failed a hard gate (too few trades, too short, or drawdown > 40%)"\n\n    s_champ = f_champ if champion_score is None else champion_score\n    s_chal = f_chal if challenger_score is None else challenger_score\n\n    margin = required_margin(n_candidates, complexity_delta)\n    if s_chal <= s_champ + margin:\n        return False, (f"selection fitness {s_chal:.3f} did not clear champion "\n                       f"{s_champ:.3f} + required margin {margin:.3f}")\n\n    # A challenger must not be worse on the merged record either — clearing the\n    # selection metric while quietly degrading the aggregate is not progress.\n    if f_chal < f_champ:\n        return False, (f"merged fitness regressed: {f_chal:.3f} vs champion {f_champ:.3f}")\n\n    dd_champ = abs(champion.get("max_dd", 0.0)) or 1e-9\n    dd_chal = abs(challenger.get("max_dd", 0.0))\n    if dd_chal > dd_champ * DD_REGRESSION_TOLERANCE:\n        return False, (f"drawdown regression: {dd_chal:.1%} vs champion {dd_champ:.1%} "\n                       f"(tolerance x{DD_REGRESSION_TOLERANCE})")\n\n    return True, (f"selection fitness {s_chal:.3f} > {s_champ:.3f} + {margin:.3f}, "\n                  f"merged {f_chal:.3f} >= {f_champ:.3f}, "\n                  f"drawdown {dd_chal:.1%} within tolerance")\n\n\ndef holdout_accepts(champion_holdout: float, challenger_holdout: float,\n                    n_draws: int = 1) -> tuple[bool, str]:\n    """The sealed-holdout gate.\n\n    The holdout is not re-drawn between runs. It is the newest HOLDOUT_FRAC of\n    a history that grows by one bar a day, so a system evolving for months\n    interrogates substantially the same bars every time it promotes. Every\n    candidate ever compared against it is another draw from one urn, and the\n    best of N draws beats an equal champion by luck alone often enough to\n    manufacture a lineage out of noise.\n\n    So the correction that guards the selection metric guards this one too. It\n    applies to the *cumulative* number of draws, which — unlike the\n    per-champion proposal set — is never reset by a promotion. Resetting it is\n    exactly what a mined holdout would look like from the inside: a clean gate\n    passed over and over, each time from a fresh count of one.\n\n    This margin uses `HOLDOUT_SIGMA`, not `MULTIPLE_TESTING_SIGMA` — a single\n    holdout window is a noisier estimate than a fold-aggregate, so the same\n    k-draw correction needs a larger sigma to protect against the same amount\n    of luck. Until 2026-08-21 this used `MULTIPLE_TESTING_SIGMA` as a\n    knowingly-too-small placeholder (this docstring said so: "measure the\n    sigma before trusting the number"); `holdout-noise`\'s block bootstrap has\n    now measured it (see `HOLDOUT_SIGMA`\'s definition and AMENDMENTS.md), and\n    `HOLDOUT_SIGMA` is that measurement, not a guess. It is still likely a\n    floor rather than the true value: a candidate only reaches this gate\n    after ranking top-3 on folds that correlate with it, so it arrives\n    pre-selected upward, and `HOLDOUT_SIGMA` doesn\'t capture that second\n    effect, only realized-path resampling noise.\n    """\n    if not math.isfinite(challenger_holdout):\n        return False, "challenger produced no finite holdout fitness"\n    if not math.isfinite(champion_holdout):\n        return True, "champion has no finite holdout fitness to beat"\n    margin = required_margin(n_draws, 0, sigma=HOLDOUT_SIGMA)\n    if challenger_holdout <= champion_holdout + margin:\n        return False, (f"failed sealed holdout: {challenger_holdout:.3f} did not clear "\n                       f"champion {champion_holdout:.3f} + margin {margin:.3f} "\n                       f"({n_draws} cumulative draws against this holdout)")\n    return True, (f"holdout {challenger_holdout:.3f} > champion {champion_holdout:.3f} "\n                  f"+ margin {margin:.3f} ({n_draws} cumulative draws)")\n\n\n# ---------------------------------------------------------------------------\n# Integrity\n# ---------------------------------------------------------------------------\n\n_HERE = os.path.dirname(os.path.abspath(__file__))\n_PROTECTED = ["__init__.py", os.path.join("..", "core", "portfolio.py")]\n\n# When running as a single-file bundle there are no source files on disk, so\n# the runner hands over the embedded source text instead. Same guarantee: we\n# still hash the exact bytes that are about to be executed.\nEMBEDDED_SOURCES: dict[str, str] = {}\n\n\ndef checksum() -> str:\n    h = hashlib.sha256()\n    if EMBEDDED_SOURCES:\n        for key in ("constitution", "core.portfolio"):\n            h.update(EMBEDDED_SOURCES.get(key, "").encode())\n        return h.hexdigest()[:16]\n    for rel in _PROTECTED:\n        p = os.path.normpath(os.path.join(_HERE, rel))\n        with open(p, "rb") as f:\n            h.update(f.read())\n    return h.hexdigest()[:16]\n\n\ndef verify(manifest_path: str | None = None) -> tuple[bool, str]:\n    """Fail loud if the scoreboard moved."""\n    manifest_path = manifest_path or os.path.join(_HERE, "MANIFEST")\n    cur = checksum()\n    if not os.path.exists(manifest_path):\n        with open(manifest_path, "w") as f:\n            f.write(cur + "\\n")\n        return True, f"constitution sealed at {cur}"\n    with open(manifest_path) as f:\n        recorded = f.read().strip()\n    if recorded != cur:\n        return False, (f"CONSTITUTION MODIFIED: expected {recorded}, found {cur}. "\n                       "A human must review and re-seal before any run.")\n    return True, f"constitution verified {cur}"\n'
_SRC['core'] = ''
_SRC['core.types'] = '"""Message contracts between agents.\n\nFrozen dataclasses, not dicts. If two agents disagree about a field name, that\nshould be an error at write-time, not a silent None three layers downstream.\nEvery one of these gets written to the decision log.\n"""\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass, field, asdict\nfrom typing import Any\n\n\n@dataclass(frozen=True)\nclass Features:\n    """What the Analyst extracts per symbol. The *only* view of the market that\n    any downstream agent gets."""\n    symbol: str\n    price: float\n    ret_1: float          # last-bar return\n    ret_5: float\n    ret_20: float\n    trend: float          # (fast MA / slow MA) - 1\n    slope: float          # normalised slope of the fast MA\n    rsi: float            # 0..100\n    vol: float            # annualised realised vol\n    vol_ratio: float      # short vol / long vol; >1 = vol expanding\n    dd_from_high: float   # <= 0\n    dist_ma: float        # (price / slow MA) - 1\n    zscore: float         # price z-score vs slow window\n    volume_shock: float   # volume vs its own average\n    breakout: float       # (price / N-bar high) - 1 ; >= 0 means new high\n    rank_mom: float       # cross-sectional momentum rank 0..1\n\n    def as_dict(self) -> dict[str, Any]:\n        return asdict(self)\n\n\n@dataclass(frozen=True)\nclass Briefing:\n    ts: str\n    regime: str                     # "bull" | "bear" | "chop" | "crisis"\n    regime_score: float             # -1..1\n    breadth: float                  # fraction of universe in uptrend\n    features: dict[str, Features]\n    equity: float\n    cash_pct: float\n    open_positions: dict[str, float]  # symbol -> weight\n\n\n@dataclass(frozen=True)\nclass Intent:\n    agent: str\n    symbol: str\n    side: str                 # "buy" | "sell" | "hold"\n    conviction: float         # 0..1\n    horizon: int              # bars\n    rationale: str\n    genes_used: dict[str, Any] = field(default_factory=dict)\n\n\n@dataclass(frozen=True)\nclass Proposal:\n    agent: str\n    ts: str\n    stance: str               # one-line temperament note\n    intents: tuple[Intent, ...]\n\n\n@dataclass(frozen=True)\nclass Veto:\n    symbol: str\n    side: str\n    by: str\n    reason: str\n\n\n@dataclass\nclass Order:\n    symbol: str\n    side: str                 # "buy" | "sell"\n    quote_amount: float = 0.0   # for buys\n    fraction: float = 0.0       # for sells\n    reason_chain: list[str] = field(default_factory=list)\n    conviction: float = 0.0\n    agreement: float = 0.0\n\n\n@dataclass\nclass Verdict:\n    ts: str\n    orders: list[Order]\n    vetoes: list[Veto]\n    agreement_score: float\n    notes: str = ""\n    by: str = "risk_judge"\n\n\n@dataclass\nclass Mutation:\n    kind: str                 # "tune" | "add_agent" | "remove_agent" | "reweight" | "universe"\n    target: str\n    patch: dict[str, Any]\n    hypothesis: str\n    proposed_by: str = "researcher"\n    ts: str = ""\n    complexity_delta: int = 0\n'
_SRC['core.market'] = '"""Market data layer.\n\nSingle responsibility: give the rest of the system clean OHLCV bars, and make\nlookahead bias structurally impossible during replay.\n\nSource: Binance public market-data mirror (data-api.binance.vision).\nFree, no API key, 24/7, ~490 USDT pairs, history back to 2017.\n\nNothing above this module knows what an exchange or an asset class is. Adding\nequities later means adding a fetcher here, not touching a single agent.\n"""\nfrom __future__ import annotations\n\nimport json\nimport os\nimport time\nimport urllib.request\nimport urllib.error\nfrom dataclasses import dataclass\nfrom typing import Iterator, Sequence\n\nimport numpy as np\nimport pandas as pd\n\nBASE = "https://data-api.binance.vision/api/v3"\nCACHE_DIR = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "state", "cache")\n\n_MS = {"1h": 3_600_000, "4h": 14_400_000, "1d": 86_400_000}\n\n# Bars-per-year for each supported interval, used to annualise stats\n# (Sharpe/Sortino/turnover/CAGR) correctly regardless of which bar size a\n# genome trades on. Keyed the same as _MS so the two can never drift apart.\nBARS_PER_YEAR = {"1h": 24 * 365.25, "4h": 6 * 365.25, "1d": 365.25}\n\n\ndef _get(url: str, retries: int = 4) -> object:\n    last = None\n    for i in range(retries):\n        try:\n            with urllib.request.urlopen(url, timeout=25) as r:\n                return json.loads(r.read().decode())\n        except Exception as e:  # noqa: BLE001 - network is allowed to be flaky\n            last = e\n            time.sleep(1.5 * (i + 1))\n    raise RuntimeError(f"fetch failed: {url}: {last}")\n\n\ndef fetch_klines(symbol: str, interval: str = "1d", start_ms: int | None = None,\n                 end_ms: int | None = None) -> pd.DataFrame:\n    """Page through Binance klines. Returns a UTC-indexed OHLCV frame."""\n    step = _MS[interval]\n    if end_ms is None:\n        end_ms = int(time.time() * 1000)\n    if start_ms is None:\n        start_ms = end_ms - step * 1500\n    rows: list[list] = []\n    cursor = start_ms\n    while cursor < end_ms:\n        url = f"{BASE}/klines?symbol={symbol}&interval={interval}&startTime={cursor}&limit=1000"\n        batch = _get(url)\n        if not batch:\n            break\n        rows.extend(batch)\n        nxt = batch[-1][0] + step\n        if nxt <= cursor:\n            break\n        cursor = nxt\n        if len(batch) < 1000:\n            break\n        time.sleep(0.12)  # be a good citizen\n\n    if not rows:\n        return pd.DataFrame()\n\n    df = pd.DataFrame(rows, columns=[\n        "open_time", "open", "high", "low", "close", "volume", "close_time",\n        "quote_volume", "trades", "taker_base", "taker_quote", "ignore"])\n    df = df[df.open_time < end_ms]\n    df["ts"] = pd.to_datetime(df.open_time, unit="ms", utc=True)\n    for c in ("open", "high", "low", "close", "volume", "quote_volume"):\n        df[c] = df[c].astype(float)\n    df = df[["ts", "open", "high", "low", "close", "volume", "quote_volume"]]\n    df = df.drop_duplicates("ts").set_index("ts").sort_index()\n    return df\n\n\ndef load(symbol: str, interval: str = "1d", years: float = 4.0,\n         refresh: bool = False) -> pd.DataFrame:\n    """Cached loader — the cache only ever grows.\n\n    This used to overwrite the cache with whatever window the caller asked for,\n    which meant a live tick wanting 1.5 years silently truncated the 4 years the\n    backtest folds depend on. Now: keep the union, fetch only the missing ends.\n    """\n    os.makedirs(CACHE_DIR, exist_ok=True)\n    path = os.path.join(CACHE_DIR, f"{symbol}_{interval}.pkl")\n    step = _MS[interval]\n    end = int(time.time() * 1000)\n    want_start = end - int(years * 365.25 * 86_400_000)\n\n    cached = pd.DataFrame()\n    if os.path.exists(path):\n        try:\n            cached = pd.read_pickle(path)\n        except Exception:  # noqa: BLE001 - corrupt cache -> refetch\n            cached = pd.DataFrame()\n\n    if cached.empty:\n        df = fetch_klines(symbol, interval, want_start, end)\n        if not df.empty:\n            df.to_pickle(path)\n        return df\n\n    have_start = int(cached.index[0].timestamp() * 1000)\n    have_end = int(cached.index[-1].timestamp() * 1000)\n    pieces = [cached]\n\n    if want_start < have_start - step:                      # need older history\n        older = fetch_klines(symbol, interval, want_start, have_start)\n        if not older.empty:\n            pieces.insert(0, older)\n    if refresh and end > have_end + step:                    # need newer bars\n        newer = fetch_klines(symbol, interval, have_end + step, end)\n        if not newer.empty:\n            pieces.append(newer)\n\n    df = (pd.concat(pieces) if len(pieces) > 1 else cached)\n    df = df[~df.index.duplicated(keep="last")].sort_index()\n    if len(pieces) > 1:\n        df.to_pickle(path)\n    return df\n\n\ndef load_universe(symbols: Sequence[str], interval: str = "1d",\n                  years: float = 4.0, refresh: bool = False) -> dict[str, pd.DataFrame]:\n    out: dict[str, pd.DataFrame] = {}\n    for s in symbols:\n        df = load(s, interval, years, refresh)\n        if len(df) > 200:\n            out[s] = df\n    return out\n\n\n# ---------------------------------------------------------------------------\n# Replay\n# ---------------------------------------------------------------------------\n\n@dataclass(frozen=True)\nclass Bar:\n    ts: pd.Timestamp\n    open: float\n    high: float\n    low: float\n    close: float\n    volume: float\n\n\nclass ReplayWindow:\n    """A read-only view of history *up to and including* bar index i.\n\n    Agents receive one of these and physically cannot see the future: the\n    underlying arrays are sliced before they\'re handed over. This is the single\n    most important anti-bug measure in the whole project — lookahead bias is\n    the reason most backtests are fiction.\n    """\n\n    __slots__ = ("_data", "_arr", "_i", "ts")\n\n    def __init__(self, data: dict[str, pd.DataFrame], i: int, ts: pd.Timestamp,\n                 arrays: dict[str, dict[str, np.ndarray]] | None = None):\n        self._data = data\n        # Pre-extracted numpy columns. Slicing pandas 12 symbols x 400 bars per\n        # backtest was ~85% of evolution runtime; slicing numpy views is free,\n        # and evolution throughput is the budget that decides how much this\n        # system can learn per hour.\n        self._arr = arrays or {}\n        self._i = i\n        self.ts = ts\n\n    def _col(self, symbol: str, col: str, n: int) -> np.ndarray:\n        a = self._arr.get(symbol, {}).get(col)\n        if a is None:\n            df = self._data.get(symbol)\n            if df is None or col not in df:\n                return np.empty(0)\n            a = df[col].to_numpy(dtype=float)\n        lo = max(0, self._i + 1 - n)\n        return a[lo:self._i + 1]\n\n    def history(self, symbol: str, n: int = 300) -> pd.DataFrame:\n        df = self._data.get(symbol)\n        if df is None:\n            return pd.DataFrame()\n        lo = max(0, self._i + 1 - n)\n        return df.iloc[lo:self._i + 1]\n\n    def closes(self, symbol: str, n: int = 300) -> np.ndarray:\n        return self._col(symbol, "close", n)\n\n    def volumes(self, symbol: str, n: int = 300) -> np.ndarray:\n        return self._col(symbol, "volume", n)\n\n    def last_close(self, symbol: str) -> float | None:\n        df = self._data.get(symbol)\n        if df is None or self._i >= len(df):\n            return None\n        v = df["close"].iat[self._i]\n        return None if pd.isna(v) else float(v)\n\n    def symbols(self) -> list[str]:\n        return list(self._data.keys())\n\n\nclass Replay:\n    """Aligns a multi-symbol universe onto one timeline and walks it forward.\n\n    Execution convention: a decision made on the close of bar i is filled on\n    the *open* of bar i+1. No exceptions. That one rule kills an entire class\n    of accidentally-profitable backtests.\n    """\n\n    def __init__(self, data: dict[str, pd.DataFrame]):\n        idx = None\n        for df in data.values():\n            idx = df.index if idx is None else idx.union(df.index)\n        self.index: pd.DatetimeIndex = idx if idx is not None else pd.DatetimeIndex([])\n        # reindex every symbol onto the shared timeline; missing bars stay NaN\n        self.data = {s: df.reindex(self.index) for s, df in data.items()}\n        # extract once, slice many\n        self.arrays: dict[str, dict[str, np.ndarray]] = {\n            s: {c: df[c].to_numpy(dtype=float) for c in ("open", "high", "low", "close", "volume")\n                if c in df}\n            for s, df in self.data.items()}\n\n    def __len__(self) -> int:\n        return len(self.index)\n\n    def next_open(self, symbol: str, i: int) -> float | None:\n        """Fill price for a decision taken at bar i."""\n        a = self.arrays.get(symbol, {}).get("open")\n        if a is None or i + 1 >= len(a):\n            return None\n        v = a[i + 1]\n        return None if np.isnan(v) else float(v)\n\n    def close_at(self, symbol: str, i: int) -> float | None:\n        a = self.arrays.get(symbol, {}).get("close")\n        if a is None or i >= len(a):\n            return None\n        v = a[i]\n        return None if np.isnan(v) else float(v)\n\n    def walk(self, start: int = 0, end: int | None = None) -> Iterator[tuple[int, ReplayWindow]]:\n        end = len(self.index) - 1 if end is None else min(end, len(self.index) - 1)\n        for i in range(start, end):\n            yield i, ReplayWindow(self.data, i, self.index[i], self.arrays)\n\n\ndef top_symbols_by_volume(n: int = 20, quote: str = "USDT",\n                          exclude_stables: bool = True) -> list[str]:\n    """Pick a liquid universe from live 24h stats. Deliberately not curated by\n    hand — the genome decides the universe, and it should be able to change it."""\n    stables = {"USDC", "TUSD", "BUSD", "FDUSD", "DAI", "USDP", "EUR", "TRY", "BRL",\n               "AEUR", "USD1", "XUSD", "USDE"}\n    data = _get(f"{BASE}/ticker/24hr")\n    rows = []\n    for t in data:  # type: ignore[union-attr]\n        s = t["symbol"]\n        if not s.endswith(quote):\n            continue\n        base = s[: -len(quote)]\n        if exclude_stables and (base in stables or base.startswith("USD")):\n            continue\n        if any(base.endswith(k) for k in ("UPUSDT", "DOWNUSDT", "UP", "DOWN", "BULL", "BEAR")):\n            continue\n        try:\n            rows.append((s, float(t["quoteVolume"])))\n        except (KeyError, ValueError):\n            continue\n    rows.sort(key=lambda x: -x[1])\n    return [s for s, _ in rows[:n]]\n'
_SRC['core.portfolio'] = '"""Paper broker + portfolio accounting.\n\nThis file lives under the *constitution* in spirit: the Researcher may never\npropose changes to it. If the thing that measures money can be edited by the\nthing being measured, every number downstream is fiction.\n\nConventions:\n  - Long-only for v0.1 (shorting comes later, with borrow costs modelled).\n  - Decision at close of bar i  ->  fill at open of bar i+1.\n  - Fees and slippage always charged. A backtest without costs is a daydream.\n"""\nfrom __future__ import annotations\n\nimport math\nfrom dataclasses import dataclass, field, asdict\nfrom typing import Any\n\nimport numpy as np\n\n\n@dataclass\nclass Fill:\n    ts: str\n    symbol: str\n    side: str            # "buy" | "sell"\n    qty: float\n    price: float         # effective price incl. slippage\n    ref_price: float     # unslipped reference\n    fee: float\n    reason: str\n\n\n@dataclass\nclass Position:\n    symbol: str\n    qty: float = 0.0\n    avg_cost: float = 0.0\n    opened_ts: str | None = None\n    peak_price: float = 0.0     # for trailing stops\n    bars_held: int = 0\n    entry_agents: tuple[str, ...] = ()   # who talked us into this\n\n    @property\n    def is_open(self) -> bool:\n        return self.qty > 1e-12\n\n\n@dataclass\nclass ClosedTrade:\n    symbol: str\n    qty: float\n    entry_price: float\n    exit_price: float\n    entry_ts: str\n    exit_ts: str\n    pnl: float\n    pnl_pct: float\n    bars_held: int\n    exit_reason: str\n    entry_agents: tuple[str, ...] = ()\n\n\nclass PaperBroker:\n    """Imaginary money, real accounting."""\n\n    def __init__(self, cash: float = 10_000.0, fee_bps: float = 10.0,\n                 slippage_bps: float = 5.0, min_order: float = 25.0):\n        self.start_cash = cash\n        self.cash = cash\n        self.fee_bps = fee_bps\n        self.slippage_bps = slippage_bps\n        self.min_order = min_order\n        self.positions: dict[str, Position] = {}\n        self.fills: list[Fill] = []\n        self.closed: list[ClosedTrade] = []\n        self.nav_history: list[tuple[str, float]] = []\n        self.peak_nav = cash\n        self.halted = False\n        self.just_halted = False\n        self.halt_bars_left = 0\n        self.halt_count = 0\n        self.halt_reason = ""\n\n    # -- valuation ---------------------------------------------------------\n    def equity(self, prices: dict[str, float]) -> float:\n        v = self.cash\n        for sym, p in self.positions.items():\n            if p.is_open:\n                px = prices.get(sym)\n                if px is not None and not math.isnan(px):\n                    v += p.qty * px\n        return v\n\n    def exposure(self, prices: dict[str, float]) -> float:\n        eq = self.equity(prices)\n        if eq <= 0:\n            return 0.0\n        invested = eq - self.cash\n        return invested / eq\n\n    def position_weight(self, symbol: str, prices: dict[str, float]) -> float:\n        eq = self.equity(prices)\n        p = self.positions.get(symbol)\n        if not p or not p.is_open or eq <= 0:\n            return 0.0\n        px = prices.get(symbol, 0.0)\n        return (p.qty * px) / eq\n\n    # -- execution ---------------------------------------------------------\n    def buy(self, ts: str, symbol: str, quote_amount: float, price: float,\n            reason: str = "", agents: tuple[str, ...] = ()) -> Fill | None:\n        if self.halted or price is None or price <= 0:\n            return None\n        quote_amount = min(quote_amount, self.cash)\n        if quote_amount < self.min_order:\n            return None\n        eff = price * (1 + self.slippage_bps / 10_000)\n        fee = quote_amount * self.fee_bps / 10_000\n        qty = (quote_amount - fee) / eff\n        if qty <= 0:\n            return None\n\n        pos = self.positions.setdefault(symbol, Position(symbol))\n        new_qty = pos.qty + qty\n        pos.avg_cost = (pos.avg_cost * pos.qty + eff * qty) / new_qty if new_qty > 0 else eff\n        pos.qty = new_qty\n        if pos.opened_ts is None:\n            pos.opened_ts = ts\n            pos.bars_held = 0\n            pos.entry_agents = tuple(agents)\n        elif agents:\n            pos.entry_agents = tuple(sorted(set(pos.entry_agents) | set(agents)))\n        pos.peak_price = max(pos.peak_price, price)\n        self.cash -= quote_amount\n\n        f = Fill(ts, symbol, "buy", qty, eff, price, fee, reason)\n        self.fills.append(f)\n        return f\n\n    def sell(self, ts: str, symbol: str, fraction: float, price: float,\n             reason: str = "") -> Fill | None:\n        pos = self.positions.get(symbol)\n        if not pos or not pos.is_open or price is None or price <= 0:\n            return None\n        fraction = max(0.0, min(1.0, fraction))\n        qty = pos.qty * fraction\n        if qty <= 0:\n            return None\n        eff = price * (1 - self.slippage_bps / 10_000)\n        gross = qty * eff\n        fee = gross * self.fee_bps / 10_000\n        proceeds = gross - fee\n        if gross < self.min_order and fraction < 1.0:\n            return None  # don\'t trade dust\n\n        pnl = (eff - pos.avg_cost) * qty - fee\n        self.cash += proceeds\n        entry_ts = pos.opened_ts or ts\n        entry_px = pos.avg_cost\n        bars = pos.bars_held\n        pos.qty -= qty\n\n        self.closed.append(ClosedTrade(\n            symbol=symbol, qty=qty, entry_price=entry_px, exit_price=eff,\n            entry_ts=entry_ts, exit_ts=ts, pnl=pnl,\n            pnl_pct=(eff / entry_px - 1) if entry_px > 0 else 0.0,\n            bars_held=bars, exit_reason=reason, entry_agents=pos.entry_agents))\n\n        if not pos.is_open:\n            self.positions.pop(symbol, None)\n\n        f = Fill(ts, symbol, "sell", qty, eff, price, fee, reason)\n        self.fills.append(f)\n        return f\n\n    # -- bookkeeping -------------------------------------------------------\n    def mark(self, ts: str, prices: dict[str, float], dd_halt: float = 0.25,\n             cooldown: int = 20) -> float:\n        """Mark to market, age positions, run the circuit breaker.\n\n        The breaker is a cooldown, not a death sentence. An earlier version\n        latched permanently, which meant a single bad month turned the rest of\n        the backtest into a flat line — measuring how fast the system died\n        rather than how well it traded. On trip: flatten, freeze for `cooldown`\n        bars, re-baseline the peak, resume.\n        """\n        for sym, pos in self.positions.items():\n            if pos.is_open:\n                pos.bars_held += 1\n                px = prices.get(sym)\n                if px:\n                    pos.peak_price = max(pos.peak_price, px)\n        nav = self.equity(prices)\n        self.nav_history.append((ts, nav))\n        self.just_halted = False\n\n        if self.halted:\n            self.halt_bars_left -= 1\n            if self.halt_bars_left <= 0:\n                self.halted = False\n                self.peak_nav = nav          # fresh baseline; don\'t re-trip instantly\n                self.halt_reason = ""\n            return nav\n\n        self.peak_nav = max(self.peak_nav, nav)\n        if self.peak_nav > 0 and (nav / self.peak_nav - 1) < -abs(dd_halt):\n            self.halted = True\n            self.just_halted = True\n            self.halt_bars_left = cooldown\n            self.halt_count += 1\n            self.halt_reason = (f"circuit breaker: drawdown {nav / self.peak_nav - 1:.1%} "\n                                f"< -{dd_halt:.0%} (freeze {cooldown} bars)")\n        return nav\n\n    # -- results -----------------------------------------------------------\n    def nav_series(self) -> np.ndarray:\n        return np.array([v for _, v in self.nav_history], dtype=float)\n\n    def stats(self, bars_per_year: float = 365.0) -> dict[str, Any]:\n        nav = self.nav_series()\n        if len(nav) < 3:\n            return {"error": "insufficient history", "trades": len(self.closed)}\n        rets = np.diff(nav) / np.maximum(nav[:-1], 1e-9)\n        total = nav[-1] / nav[0] - 1\n        yrs = max(len(nav) / bars_per_year, 1e-6)\n        cagr = (nav[-1] / nav[0]) ** (1 / yrs) - 1 if nav[0] > 0 else 0.0\n        vol = float(np.std(rets, ddof=1)) * math.sqrt(bars_per_year) if len(rets) > 2 else 0.0\n        downside = rets[rets < 0]\n        dd_dev = float(np.std(downside, ddof=1)) * math.sqrt(bars_per_year) if len(downside) > 2 else 0.0\n        sharpe = float(np.mean(rets)) * bars_per_year / vol if vol > 1e-9 else 0.0\n        sortino = float(np.mean(rets)) * bars_per_year / dd_dev if dd_dev > 1e-9 else 0.0\n        peaks = np.maximum.accumulate(nav)\n        max_dd = float(np.min(nav / np.maximum(peaks, 1e-9) - 1))\n        wins = [t for t in self.closed if t.pnl > 0]\n        gross_win = sum(t.pnl for t in wins)\n        gross_loss = -sum(t.pnl for t in self.closed if t.pnl <= 0)\n        turnover = sum(f.qty * f.price for f in self.fills) / max(nav[0], 1e-9) / yrs\n        return {\n            "start_nav": float(nav[0]), "end_nav": float(nav[-1]),\n            "total_return": float(total), "cagr": float(cagr),\n            "vol": vol, "sharpe": sharpe, "sortino": sortino,\n            "max_dd": max_dd, "bars": len(nav),\n            "trades": len(self.closed),\n            "win_rate": len(wins) / len(self.closed) if self.closed else 0.0,\n            "profit_factor": gross_win / gross_loss if gross_loss > 1e-9 else (\n                float("inf") if gross_win > 0 else 0.0),\n            "avg_trade_pct": float(np.mean([t.pnl_pct for t in self.closed])) if self.closed else 0.0,\n            "avg_bars_held": float(np.mean([t.bars_held for t in self.closed])) if self.closed else 0.0,\n            "turnover_annual": float(turnover),\n            "fees_paid": float(sum(f.fee for f in self.fills)),\n            "halted": self.halted, "halt_reason": self.halt_reason,\n            "halt_count": self.halt_count,\n        }\n\n    # -- persistence (the live account must survive an ephemeral container) --\n    def to_state(self) -> dict[str, Any]:\n        return {\n            "start_cash": self.start_cash, "cash": self.cash,\n            "fee_bps": self.fee_bps, "slippage_bps": self.slippage_bps,\n            "min_order": self.min_order,\n            "positions": {s: asdict(p) for s, p in self.positions.items() if p.is_open},\n            "fills": [asdict(f) for f in self.fills],\n            "closed": [asdict(t) for t in self.closed],\n            "nav_history": self.nav_history,\n            "peak_nav": self.peak_nav, "halted": self.halted,\n            "halt_bars_left": self.halt_bars_left, "halt_count": self.halt_count,\n            "halt_reason": self.halt_reason,\n        }\n\n    @classmethod\n    def from_state(cls, st: dict[str, Any]) -> "PaperBroker":\n        b = cls(cash=st.get("start_cash", 10_000.0), fee_bps=st.get("fee_bps", 10.0),\n                slippage_bps=st.get("slippage_bps", 5.0), min_order=st.get("min_order", 25.0))\n        b.cash = st.get("cash", b.cash)\n        b.positions = {s: Position(**{**p, "entry_agents": tuple(p.get("entry_agents", ()))})\n                       for s, p in st.get("positions", {}).items()}\n        b.fills = [Fill(**f) for f in st.get("fills", [])]\n        b.closed = [ClosedTrade(**{**t, "entry_agents": tuple(t.get("entry_agents", ()))})\n                    for t in st.get("closed", [])]\n        b.nav_history = [tuple(x) for x in st.get("nav_history", [])]\n        b.peak_nav = st.get("peak_nav", b.start_cash)\n        b.halted = st.get("halted", False)\n        b.halt_bars_left = st.get("halt_bars_left", 0)\n        b.halt_count = st.get("halt_count", 0)\n        b.halt_reason = st.get("halt_reason", "")\n        return b\n\n    def to_dict(self) -> dict[str, Any]:\n        return {\n            "stats": self.stats(),\n            "nav_history": self.nav_history,\n            "fills": [asdict(f) for f in self.fills],\n            "closed": [asdict(t) for t in self.closed],\n            "open_positions": {s: asdict(p) for s, p in self.positions.items() if p.is_open},\n        }\n'
_SRC['core.genome'] = '"""The genome — everything the system is allowed to change about itself.\n\nCode is mechanism. Genome is policy. There should be no strategy number\nhardcoded anywhere in agents/ — if a constant matters, it belongs here, where\nthe Researcher can propose changing it and the Superior Judge can veto.\n"""\nfrom __future__ import annotations\n\nimport copy\nimport json\nimport os\nimport time\nfrom datetime import datetime, timezone\nfrom typing import Any\n\nGENOME_DIR = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))),\n                          "state", "genomes")\n\n\ndef _now() -> str:\n    return datetime.now(timezone.utc).isoformat(timespec="seconds")\n\n\nSEED_GENOME: dict[str, Any] = {\n    "version": 1,\n    "parent": None,\n    "created": None,\n    "note": "seed roster — hand-written starting point, expected to be replaced by evolution",\n    # Which OHLCV bar size this genome trades and is scored on. "1h" | "4h" | "1d".\n    # Gene periods below (trend_fast/slow, rsi_len, breakout_len, regime_ma,\n    # max_bars_held, ...) are expressed in *bars*, not wall-clock time, so\n    # switching this without re-tuning them changes what those numbers mean.\n    "bar_interval": "1d",\n    # 27 liquid USDT pairs with 4+ years of history. Breadth is not cosmetic:\n    # a fitness estimate over 12 symbols is too noisy to tell a real edge from\n    # luck, so the acceptance gates reject everything and nothing can ever be\n    # learned. More symbols -> more trades -> a tighter estimate -> the gates\n    # become passable by genuine improvements instead of only by noise.\n    # PAXG (gold) is deliberately included as a non-crypto-correlated asset.\n    "universe": ["BTCUSDT", "ETHUSDT", "BNBUSDT", "SOLUSDT", "XRPUSDT",\n                 "ADAUSDT", "DOGEUSDT", "LINKUSDT", "AVAXUSDT", "LTCUSDT",\n                 "DOTUSDT", "TRXUSDT", "ZECUSDT", "UNIUSDT", "NEARUSDT",\n                 "INJUSDT", "FETUSDT", "AAVEUSDT", "XLMUSDT", "SHIBUSDT",\n                 "BCHUSDT", "CRVUSDT", "FILUSDT", "ATOMUSDT", "ICPUSDT",\n                 "HBARUSDT", "PAXGUSDT"],\n    "agents": {\n        "analyst": {\n            "enabled": True,\n            "genes": {\n                "trend_fast": 10, "trend_slow": 50,\n                "rsi_len": 14,\n                "vol_short": 10, "vol_long": 40,\n                "breakout_len": 20, "z_len": 30,\n                "regime_ma": 50, "regime_anchor": "BTCUSDT",\n                "volume_len": 20,\n            },\n        },\n        "consult_risky": {\n            "enabled": True, "weight": 1.0,\n            "genes": {\n                "min_breakout": -0.02,   # within 2% of the N-bar high\n                "min_rank_mom": 0.70,    # top 30% of the universe by momentum\n                "min_slope": 0.0,\n                "rsi_max": 82.0,         # even a momentum chaser has a limit\n                "min_vol_ratio": 0.0,\n                "conviction_scale": 1.20,\n                "exit_rsi": 88.0,\n                "exit_trend_below": -0.03,\n            },\n        },\n        "consult_moderate": {\n            "enabled": True, "weight": 1.0,\n            "genes": {\n                "min_trend": 0.005,\n                "min_slope": 0.0,\n                "rsi_lo": 45.0, "rsi_hi": 72.0,\n                "min_rank_mom": 0.50,\n                "max_vol": 1.60,\n                "conviction_scale": 1.0,\n                "exit_trend_below": 0.0,\n                "exit_rsi": 80.0,\n            },\n        },\n        "consult_conservative": {\n            "enabled": True, "weight": 1.0,\n            "genes": {\n                "rsi_buy_below": 38.0,\n                "z_buy_below": -0.8,\n                "require_uptrend": True,     # only buy dips inside an uptrend\n                "min_trend": -0.01,\n                "max_vol": 1.10,\n                "max_dd_from_high": -0.35,   # don\'t catch a falling knife\n                "conviction_scale": 0.80,\n                "take_profit": 0.12,\n                "exit_rsi": 68.0,\n            },\n        },\n        "risk_judge": {\n            "enabled": True,\n            "genes": {\n                "base_size_pct": 0.12,\n                "unanimous_bonus": 1.60,\n                "two_agree_bonus": 1.20,\n                "lone_voice_scale": 0.60,\n                "min_conviction": 0.30,\n                "max_positions": 6,\n                "max_position_pct": 0.25,\n                "cash_floor_pct": 0.05,\n                "regime_scale": {"bull": 1.0, "chop": 0.6, "bear": 0.25, "crisis": 0.0},\n                "sell_conviction_threshold": 0.35,\n                "scale_in_allowed": True,\n            },\n        },\n        "superior_judge": {\n            "enabled": True,\n            "genes": {\n                "hard_max_position_pct": 0.35,\n                "hard_cash_floor_pct": 0.02,\n                "hard_max_positions": 8,\n                "block_buys_in_crisis": True,\n                "max_new_positions_per_bar": 3,\n            },\n        },\n    },\n    "risk": {\n        "stop_loss": -0.12,\n        "trailing_stop": -0.15,\n        "take_profit": 0.35,\n        "max_bars_held": 60,\n        "min_bars_held": 1,\n    },\n    "routing": {\n        "consults": ["consult_risky", "consult_moderate", "consult_conservative"],\n        "minor_judges": ["risk_judge"],\n        "final": "superior_judge",\n    },\n    "broker": {"fee_bps": 10.0, "slippage_bps": 5.0, "start_cash": 10_000.0},\n}\n\n\nclass Genome:\n    def __init__(self, data: dict[str, Any] | None = None):\n        self.data: dict[str, Any] = copy.deepcopy(data or SEED_GENOME)\n        if self.data.get("created") is None:\n            self.data["created"] = _now()\n\n    # -- access ------------------------------------------------------------\n    def genes(self, agent: str) -> dict[str, Any]:\n        return self.data["agents"].get(agent, {}).get("genes", {})\n\n    def enabled(self, agent: str) -> bool:\n        return bool(self.data["agents"].get(agent, {}).get("enabled", False))\n\n    def gene(self, agent: str, key: str, default: Any = None) -> Any:\n        return self.genes(agent).get(key, default)\n\n    @property\n    def universe(self) -> list[str]:\n        return list(self.data["universe"])\n\n    @property\n    def bar_interval(self) -> str:\n        """"1h" | "4h" | "1d" — defaults to "1d" for genomes saved before this\n        field existed, so old lineage/champion files keep loading unchanged."""\n        return str(self.data.get("bar_interval", "1d"))\n\n    @property\n    def risk(self) -> dict[str, Any]:\n        return self.data["risk"]\n\n    @property\n    def version(self) -> int:\n        return int(self.data["version"])\n\n    @property\n    def consults(self) -> list[str]:\n        return [a for a in self.data["routing"]["consults"] if self.enabled(a)]\n\n    def complexity(self) -> int:\n        """Crude but honest: number of live agents + number of live genes.\n        Used by the acceptance rule to charge rent on added machinery."""\n        n = 0\n        for name, spec in self.data["agents"].items():\n            if spec.get("enabled"):\n                n += 1 + len(spec.get("genes", {}))\n        return n\n\n    # -- mutation ----------------------------------------------------------\n    def child(self, patches: list[tuple[str, Any]], note: str = "") -> "Genome":\n        """Return a new genome with dotted-path patches applied. Never mutates\n        self — lineage must stay immutable or the audit trail is worthless."""\n        d = copy.deepcopy(self.data)\n        for path, value in patches:\n            node = d\n            parts = path.split(".")\n            for p in parts[:-1]:\n                node = node.setdefault(p, {})\n            node[parts[-1]] = value\n        d["parent"] = self.data.get("version")\n        d["version"] = int(self.data.get("version", 0)) + 1\n        d["created"] = _now()\n        d["note"] = note\n        return Genome(d)\n\n    # -- persistence -------------------------------------------------------\n    def save(self, tag: str | None = None) -> str:\n        os.makedirs(GENOME_DIR, exist_ok=True)\n        name = tag or f"v{self.version}"\n        path = os.path.join(GENOME_DIR, f"{name}.json")\n        with open(path, "w") as f:\n            json.dump(self.data, f, indent=2)\n        return path\n\n    @classmethod\n    def load(cls, path_or_version: str | int) -> "Genome":\n        if isinstance(path_or_version, int):\n            path = os.path.join(GENOME_DIR, f"v{path_or_version}.json")\n        elif os.path.exists(path_or_version):\n            path = path_or_version\n        else:\n            path = os.path.join(GENOME_DIR, f"{path_or_version}.json")\n        with open(path) as f:\n            return cls(json.load(f))\n\n    @classmethod\n    def champion(cls) -> "Genome":\n        p = os.path.join(GENOME_DIR, "champion.json")\n        if os.path.exists(p):\n            return cls.load(p)\n        g = cls()\n        g.save("champion")\n        g.save("v1")\n        return g\n\n    def promote(self) -> None:\n        self.save(f"v{self.version}")\n        self.save("champion")\n'
_SRC['core.live'] = '"""LIVE PAPER TRADING — real prices, imaginary money, one bar at a time.\n\nThe backtest and the live run share the same Council code path. That is the\nwhole point: when the live account diverges from what the backtest said it\nwould do, that\'s a bug worth chasing, not a mystery.\n\nConvention: run shortly after 00:00 UTC. The decision is made on the last\n*closed* daily bar; the fill is the live price at the moment of execution,\nwhich is a few minutes into the new bar — the closest live analogue of the\nbacktest\'s "fill at next open".\n\nState lives in a single JSON blob so it can be parked in the Claude project\nand survive this container being reclaimed.\n"""\nfrom __future__ import annotations\n\nimport json\nimport os\nfrom datetime import datetime, timezone\nfrom typing import Any\n\nfrom agents.trader import Trader\nfrom core import market\nfrom core.genome import Genome\nfrom core.market import Replay, ReplayWindow\nfrom core.portfolio import PaperBroker\n\nSTATE_DIR = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))),\n                         "state", "live")\nSTATE_PATH = os.path.join(STATE_DIR, "account.json")\nJOURNAL_PATH = os.path.join(STATE_DIR, "journal.jsonl")\n\n\ndef _now() -> str:\n    return datetime.now(timezone.utc).isoformat(timespec="seconds")\n\n\ndef live_prices(symbols: list[str]) -> dict[str, float]:\n    """Current mid prices straight off the exchange."""\n    out: dict[str, float] = {}\n    try:\n        data = market._get(f"{market.BASE}/ticker/price")\n        book = {t["symbol"]: float(t["price"]) for t in data}  # type: ignore[union-attr]\n        for s in symbols:\n            if s in book:\n                out[s] = book[s]\n    except Exception:  # noqa: BLE001 - fall back to last close below\n        pass\n    return out\n\n\nclass LiveAccount:\n    def __init__(self, state: dict[str, Any] | None = None):\n        self.state = state or {}\n        self.genome = (Genome(self.state["genome"]) if self.state.get("genome")\n                       else Genome.champion())\n        self.broker = (PaperBroker.from_state(self.state["broker"])\n                       if self.state.get("broker") else\n                       PaperBroker(cash=float(self.genome.data["broker"]["start_cash"]),\n                                   fee_bps=float(self.genome.data["broker"]["fee_bps"]),\n                                   slippage_bps=float(self.genome.data["broker"]["slippage_bps"])))\n        self.journal: list[dict] = self.state.get("journal", [])\n        # evolution history rides along in the same durable blob — otherwise a\n        # promotion\'s reasoning is lost the moment the container is reclaimed\n        self.lineage: list[dict] = self.state.get("lineage", [])\n        self.started = self.state.get("started") or _now()\n        self.ticks = int(self.state.get("ticks", 0))\n        self.researcher_memory: dict = self.state.get("researcher_memory", {})\n        # verdicts written back onto flagged (agents.judges.flag_hard_call)\n        # journal entries by a later scheduled session reasoning about them --\n        # AGENTS.md item 4 design (b), "review after the fact" rather than\n        # gating execution. Defaults to empty so loading any state saved\n        # before this field existed round-trips unchanged.\n        self.hard_call_reviews: list[dict] = self.state.get("hard_call_reviews", [])\n\n    # -- io ----------------------------------------------------------------\n    @classmethod\n    def load(cls, path: str = STATE_PATH) -> "LiveAccount":\n        if os.path.exists(path):\n            with open(path) as f:\n                return cls(json.load(f))\n        return cls()\n\n    def save(self, path: str = STATE_PATH) -> str:\n        # dirname("live_state.json") is "" — makedirs("") raises. A bare\n        # filename is exactly what the scheduled run uses, so this crashed\n        # *after* the trade was booked and before the state was written.\n        d = os.path.dirname(path)\n        if d:\n            os.makedirs(d, exist_ok=True)\n        blob = {\n            "started": self.started, "ticks": self.ticks, "updated": _now(),\n            "genome": self.genome.data,\n            "broker": self.broker.to_state(),\n            "journal": self.journal[-400:],\n            "lineage": self.lineage[-200:],\n            "researcher_memory": self.researcher_memory,\n            "hard_call_reviews": self.hard_call_reviews,\n        }\n        with open(path, "w") as f:\n            json.dump(blob, f, indent=2, default=str)\n        return path\n\n    def add_hard_call_review(self, tick: int, verdict: str, notes: str = "") -> dict[str, Any]:\n        """Record a reasoned verdict on a flagged bar.\n\n        Never gates execution -- the tick this reviews already ran, same-pass,\n        long before this is ever called; this only appends a durable note a\n        later scheduled session (or a human) can read. Raises on a `tick`\n        that either doesn\'t exist in the journal or was never actually\n        flagged, so a typo can\'t quietly manufacture a review for a bar that\n        was never a hard call.\n        """\n        entry = next((e for e in self.journal if e.get("tick") == tick), None)\n        if entry is None:\n            raise ValueError(f"no journal entry for tick {tick}")\n        hc = (entry.get("decision") or {}).get("hard_call") or {}\n        if not hc.get("is_hard_call"):\n            raise ValueError(f"tick {tick} was not flagged as a hard call")\n        record = {\n            "tick": tick, "bar": entry.get("bar"), "reviewed_at": _now(),\n            "verdict": verdict, "notes": notes, "reasons": hc.get("reasons", []),\n        }\n        self.hard_call_reviews.append(record)\n        return record\n\n    # -- the tick ----------------------------------------------------------\n    def tick(self, use_live_price: bool = True, refresh: bool = True,\n             force: bool = False) -> dict[str, Any]:\n        from loop.engine import Council  # local import: avoids a cycle\n\n        uni = self.genome.universe\n        interval = self.genome.bar_interval\n        data = market.load_universe(uni, interval, years=1.5, refresh=refresh)\n        if not data:\n            return {"error": "no market data"}\n\n        replay = Replay(data)\n        n = len(replay)\n        if n < 80:\n            return {"error": f"not enough history ({n} bars)"}\n\n        # last fully closed daily bar. Today\'s forming bar is index n-1, so the\n        # last closed one is n-2. Never decide on a bar that isn\'t finished.\n        i = n - 2\n        bar_id = str(replay.index[i])\n\n        # Idempotency: an unattended daily job can fire twice (retry, manual\n        # re-run, clock wobble). Trading the same bar twice would double the\n        # position and corrupt the track record, so refuse politely.\n        if self.journal and self.journal[-1].get("bar") == bar_id and not force:\n            return {"skipped": f"bar {bar_id[:10]} already traded (tick {self.ticks})",\n                    "tick": self.ticks, "bar": bar_id,\n                    "nav_after": round(self.broker.equity(\n                        {s: replay.close_at(s, i) for s in replay.data\n                         if replay.close_at(s, i)}), 2)}\n\n        window = ReplayWindow(replay.data, i, replay.index[i], replay.arrays)\n        closes = {s: replay.close_at(s, i) for s in replay.data}\n        closes = {s: p for s, p in closes.items() if p}\n\n        fills = live_prices(uni) if use_live_price else {}\n        for s, p in closes.items():\n            fills.setdefault(s, p)\n\n        council = Council(self.genome, self.broker)\n        before_nav = self.broker.equity(closes)\n        before_cash = self.broker.cash\n        council.tick(window, closes, fills, log_detail=True)\n        after_nav = self.broker.equity(fills if fills else closes)\n\n        self.ticks += 1\n        entry = {\n            "ts": _now(),\n            "bar": str(replay.index[i]),\n            "tick": self.ticks,\n            "nav_before": round(before_nav, 2),\n            "nav_after": round(after_nav, 2),\n            "cash": round(self.broker.cash, 2),\n            "cash_before": round(before_cash, 2),\n            "positions": {s: round(p.qty * fills.get(s, closes.get(s, 0)), 2)\n                          for s, p in self.broker.positions.items() if p.is_open},\n            "genome_version": self.genome.version,\n            "halted": self.broker.halted,\n            "decision": council.decision_log[-1] if council.decision_log else None,\n        }\n        self.journal.append(entry)\n        return entry\n\n    # -- reporting ---------------------------------------------------------\n    def signals(self) -> str:\n        """Today\'s decision, in plain language.\n\n        This is the no-credentials path. Nothing here ever needs a brokerage\n        account, an API key, a tax ID, or KYC: prices come from a public\n        endpoint and the portfolio is tracked in this file. If real money is\n        ever involved, the system says what it would do and a human places the\n        order wherever they already have an account — the ledger stays\n        authoritative either way, because the ledger was never the broker\'s.\n        """\n        if not self.journal:\n            return "No decision recorded yet — run a tick first."\n        e = self.journal[-1]\n        d = e.get("decision") or {}\n        nav = e.get("nav_after", 0.0)\n        ret = (nav / self.broker.start_cash - 1) if self.broker.start_cash else 0.0\n\n        lines = [\n            f"Project Necrozma — decision for bar {str(e.get(\'bar\', \'\'))[:10]}  (tick {e.get(\'tick\')})",\n            f"Account: ${nav:,.2f}  ({ret:+.2%} since {str(self.started)[:10]})  "\n            f"cash ${e.get(\'cash\', 0):,.2f}",\n            f"Market read: {d.get(\'regime\', \'?\')}, breadth {d.get(\'breadth\', 0):.0%}",\n            "",\n        ]\n\n        forced = d.get("forced_exits") or []\n        orders = d.get("orders") or []\n        if not forced and not orders:\n            lines.append("  ACTION: none. Hold the current book.")\n        for f in forced:\n            lines.append(f"  SELL ALL  {f[\'symbol\']:<10s}  (mandatory) — {f[\'why\']}")\n        for o in orders:\n            if o["side"] == "sell":\n                pct = int(o.get("fraction", 1.0) * 100)\n                lines.append(f"  SELL {pct:>3d}%  {o[\'symbol\']:<10s}")\n            else:\n                lines.append(f"  BUY  ${o.get(\'amount\', 0):>8,.0f}  {o[\'symbol\']:<10s}"\n                             f"  (agreement {o.get(\'agreement\', 0):.0%})")\n            for r in o.get("why", [])[:3]:\n                lines.append(f"           └─ {r}")\n\n        book = e.get("positions") or {}\n        lines.append("")\n        lines.append("Book after this decision:")\n        if book:\n            for s, v in sorted(book.items(), key=lambda kv: -kv[1]):\n                lines.append(f"  {s:<10s} ${v:>9,.0f}   {v / max(nav, 1):>5.1%}")\n        else:\n            lines.append("  all cash")\n        return "\\n".join(lines)\n\n    def summary(self) -> dict[str, Any]:\n        bpy = market.BARS_PER_YEAR.get(self.genome.bar_interval, 365.25)\n        st = self.broker.stats(bars_per_year=bpy)\n        return {\n            "started": self.started, "ticks": self.ticks,\n            "genome_version": self.genome.version,\n            "nav": self.broker.nav_history[-1][1] if self.broker.nav_history else self.broker.cash,\n            "cash": self.broker.cash,\n            "open_positions": {s: {"qty": p.qty, "avg_cost": p.avg_cost,\n                                   "bars_held": p.bars_held,\n                                   "entry_agents": list(p.entry_agents)}\n                               for s, p in self.broker.positions.items() if p.is_open},\n            "stats": st,\n            "halted": self.broker.halted, "halt_reason": self.broker.halt_reason,\n        }\n'
_SRC['agents'] = ''
_SRC['agents.analyst'] = '"""ANALYST — the only agent that touches raw candles.\n\nEveryone downstream reasons about the Briefing it produces. That\'s a design\nchoice with teeth: it means a change to how the market is *perceived* is one\nisolated, testable gene set, and no consult can quietly invent its own private\nindicator that nobody else can audit.\n"""\nfrom __future__ import annotations\n\nimport math\n\nimport numpy as np\n\nfrom core.genome import Genome\nfrom core.market import ReplayWindow\nfrom core.types import Briefing, Features\n\n\ndef _sma(a: np.ndarray, n: int) -> float:\n    if len(a) < n or n <= 0:\n        return float("nan")\n    return float(np.mean(a[-n:]))\n\n\ndef _rsi(a: np.ndarray, n: int) -> float:\n    if len(a) < n + 1:\n        return 50.0\n    d = np.diff(a[-(n + 1):])\n    up = float(np.mean(np.clip(d, 0, None)))\n    dn = float(np.mean(np.clip(-d, 0, None)))\n    if dn < 1e-12:\n        return 100.0 if up > 0 else 50.0\n    rs = up / dn\n    return float(100 - 100 / (1 + rs))\n\n\ndef _ann_vol(a: np.ndarray, n: int, bars_per_year: float = 365.0) -> float:\n    if len(a) < n + 1:\n        return float("nan")\n    r = np.diff(a[-(n + 1):]) / np.maximum(a[-(n + 1):-1], 1e-12)\n    return float(np.std(r, ddof=1) * math.sqrt(bars_per_year)) if len(r) > 1 else float("nan")\n\n\nclass Analyst:\n    name = "analyst"\n\n    def __init__(self, genome: Genome):\n        self.g = genome\n        self.genes = genome.genes("analyst")\n\n    def brief(self, w: ReplayWindow, equity: float, cash: float,\n              weights: dict[str, float]) -> Briefing:\n        g = self.genes\n        fast = int(g.get("trend_fast", 10))\n        slow = int(g.get("trend_slow", 50))\n        need = max(slow, int(g.get("z_len", 30)), int(g.get("breakout_len", 20))) + 5\n\n        feats: dict[str, Features] = {}\n        raw_mom: dict[str, float] = {}\n\n        for sym in self.g.universe:\n            c = w.closes(sym, need + 10)\n            c = c[~np.isnan(c)]\n            if len(c) < need:\n                continue\n            price = float(c[-1])\n            ma_f = _sma(c, fast)\n            ma_s = _sma(c, slow)\n            if not (math.isfinite(ma_f) and math.isfinite(ma_s)) or ma_s <= 0:\n                continue\n\n            prev_ma_f = _sma(c[:-3], fast) if len(c) > fast + 3 else ma_f\n            slope = (ma_f / prev_ma_f - 1) if prev_ma_f > 0 else 0.0\n\n            zwin = c[-int(g.get("z_len", 30)):]\n            sd = float(np.std(zwin, ddof=1))\n            z = (price - float(np.mean(zwin))) / sd if sd > 1e-12 else 0.0\n\n            bl = int(g.get("breakout_len", 20))\n            hi = float(np.max(c[-bl:]))\n            breakout = price / hi - 1 if hi > 0 else 0.0\n\n            run_high = float(np.max(c[-slow:]))\n            dd_high = price / run_high - 1 if run_high > 0 else 0.0\n\n            v_s = _ann_vol(c, int(g.get("vol_short", 10)))\n            v_l = _ann_vol(c, int(g.get("vol_long", 40)))\n            vol_ratio = (v_s / v_l) if (math.isfinite(v_s) and math.isfinite(v_l) and v_l > 1e-9) else 1.0\n\n            vv = w.volumes(sym, int(g.get("volume_len", 20)) + 1)\n            vv = vv[~np.isnan(vv)]\n            vol_shock = 1.0\n            if len(vv) > 3 and np.mean(vv[:-1]) > 0:\n                vol_shock = float(vv[-1] / np.mean(vv[:-1]))\n\n            r1 = c[-1] / c[-2] - 1 if len(c) > 1 else 0.0\n            r5 = c[-1] / c[-6] - 1 if len(c) > 5 else 0.0\n            r20 = c[-1] / c[-21] - 1 if len(c) > 20 else 0.0\n\n            feats[sym] = Features(\n                symbol=sym, price=price, ret_1=r1, ret_5=r5, ret_20=r20,\n                trend=ma_f / ma_s - 1, slope=slope, rsi=_rsi(c, int(g.get("rsi_len", 14))),\n                vol=v_s if math.isfinite(v_s) else 0.0, vol_ratio=vol_ratio,\n                dd_from_high=dd_high, dist_ma=price / ma_s - 1, zscore=z,\n                volume_shock=vol_shock, breakout=breakout, rank_mom=0.0)\n            raw_mom[sym] = r20\n\n        # cross-sectional momentum rank: 1.0 = strongest in the universe.\n        # Relative strength matters more than absolute in a market where\n        # everything moves together.\n        if raw_mom:\n            order = sorted(raw_mom, key=lambda s: raw_mom[s])\n            n = max(len(order) - 1, 1)\n            for i, sym in enumerate(order):\n                f = feats[sym]\n                feats[sym] = Features(**{**f.as_dict(), "rank_mom": i / n})\n\n        regime, score, breadth = self._regime(w, feats)\n        return Briefing(\n            ts=str(w.ts), regime=regime, regime_score=score, breadth=breadth,\n            features=feats, equity=equity,\n            cash_pct=(cash / equity) if equity > 0 else 1.0,\n            open_positions=dict(weights))\n\n    def _regime(self, w: ReplayWindow, feats: dict[str, Features]) -> tuple[str, float, float]:\n        g = self.genes\n        anchor = g.get("regime_anchor", "BTCUSDT")\n        n = int(g.get("regime_ma", 50))\n        c = w.closes(anchor, n + 10)\n        c = c[~np.isnan(c)]\n\n        anchor_score, anchor_dd, anchor_volr = 0.0, 0.0, 1.0\n        if len(c) >= n:\n            ma = _sma(c, n)\n            anchor_score = (c[-1] / ma - 1) if ma > 0 else 0.0\n            hi = float(np.max(c[-n:]))\n            anchor_dd = c[-1] / hi - 1 if hi > 0 else 0.0\n            vs, vl = _ann_vol(c, 10), _ann_vol(c, 40)\n            if math.isfinite(vs) and math.isfinite(vl) and vl > 1e-9:\n                anchor_volr = vs / vl\n\n        breadth = (sum(1 for f in feats.values() if f.trend > 0) / len(feats)) if feats else 0.0\n        score = float(np.clip(anchor_score * 4 + (breadth - 0.5) * 2, -1, 1))\n\n        # crisis is not just "down" — it\'s down *and* violent. Distinguishing\n        # them matters: a slow bear is tradable, a crash is not.\n        if anchor_dd < -0.22 and anchor_volr > 1.35:\n            return "crisis", score, breadth\n        if anchor_score > 0.02 and breadth > 0.5:\n            return "bull", score, breadth\n        if anchor_score < -0.03 or breadth < 0.30:\n            return "bear", score, breadth\n        return "chop", score, breadth\n'
_SRC['agents.consults'] = '"""THE THREE CONSULTS.\n\nNot one strategy with a risk dial in three positions — three genuinely\ndifferent theories of where money comes from. That matters: if they were\ncorrelated, their agreement would carry no information, and the Risk Judge\'s\nwhole job (reading disagreement) would be noise.\n\n  risky        -> "buy what is already winning"      (momentum / breakout)\n  conservative -> "buy what is temporarily hated"    (mean reversion)\n  moderate     -> "buy confirmed trends, patiently"  (trend + confirmation)\n\nEach emits Intents with a rationale. The rationale is not decoration — it is\nthe raw material the Researcher mines to work out which reasoning actually pays.\n"""\nfrom __future__ import annotations\n\nfrom core.genome import Genome\nfrom core.types import Briefing, Intent, Proposal\n\n\nclass BaseConsult:\n    name = "consult"\n    stance = ""\n\n    def __init__(self, genome: Genome, name: str | None = None):\n        self.g = genome\n        if name:\n            self.name = name\n        self.genes = genome.genes(self.name)\n\n    def scale(self, x: float) -> float:\n        return max(0.0, min(1.0, x * float(self.genes.get("conviction_scale", 1.0))))\n\n    def consider(self, b: Briefing) -> Proposal:\n        raise NotImplementedError\n\n    def _wrap(self, b: Briefing, intents: list[Intent]) -> Proposal:\n        return Proposal(agent=self.name, ts=b.ts, stance=self.stance,\n                        intents=tuple(intents))\n\n\nclass RiskyConsult(BaseConsult):\n    name = "consult_risky"\n    stance = "strength begets strength — own the leaders, cut fast when they stop leading"\n\n    def consider(self, b: Briefing) -> Proposal:\n        g = self.genes\n        out: list[Intent] = []\n        for sym, f in b.features.items():\n            held = b.open_positions.get(sym, 0.0) > 0\n\n            if held and (f.rsi > g.get("exit_rsi", 88) or f.trend < g.get("exit_trend_below", -0.03)):\n                out.append(Intent(self.name, sym, "sell", 0.8, 0, (\n                    f"leadership lost: rsi {f.rsi:.0f}, trend {f.trend:+.1%}"), dict(g)))\n                continue\n\n            if (f.breakout >= g.get("min_breakout", -0.02)\n                    and f.rank_mom >= g.get("min_rank_mom", 0.7)\n                    and f.slope >= g.get("min_slope", 0.0)\n                    and f.rsi <= g.get("rsi_max", 82)\n                    and f.vol_ratio >= g.get("min_vol_ratio", 0.0)):\n                conv = self.scale(0.45 + 0.35 * f.rank_mom + 6 * max(0.0, f.breakout))\n                out.append(Intent(self.name, sym, "buy", conv, 15, (\n                    f"at/near range high (breakout {f.breakout:+.1%}), "\n                    f"momentum rank {f.rank_mom:.2f}, slope {f.slope:+.2%}"), dict(g)))\n        return self._wrap(b, out)\n\n\nclass ConservativeConsult(BaseConsult):\n    name = "consult_conservative"\n    stance = "buy fear inside strength, sell relief — and hold cash without shame"\n\n    def consider(self, b: Briefing) -> Proposal:\n        g = self.genes\n        out: list[Intent] = []\n        for sym, f in b.features.items():\n            held = b.open_positions.get(sym, 0.0) > 0\n\n            if held and f.rsi > g.get("exit_rsi", 68):\n                out.append(Intent(self.name, sym, "sell", 0.7, 0,\n                                  f"mean reversion complete: rsi {f.rsi:.0f}", dict(g)))\n                continue\n\n            if f.vol > g.get("max_vol", 1.10):\n                continue\n            if f.dd_from_high < g.get("max_dd_from_high", -0.35):\n                continue  # falling knife\n            if g.get("require_uptrend", True) and f.trend < g.get("min_trend", -0.01):\n                continue\n\n            if f.rsi <= g.get("rsi_buy_below", 38) and f.zscore <= g.get("z_buy_below", -0.8):\n                depth = min(1.0, (g.get("rsi_buy_below", 38) - f.rsi) / 20.0)\n                conv = self.scale(0.35 + 0.45 * depth)\n                out.append(Intent(self.name, sym, "buy", conv, 10, (\n                    f"oversold inside an uptrend: rsi {f.rsi:.0f}, z {f.zscore:+.2f}, "\n                    f"trend {f.trend:+.1%}"), dict(g)))\n        return self._wrap(b, out)\n\n\nclass ModerateConsult(BaseConsult):\n    name = "consult_moderate"\n    stance = "trend plus confirmation; no heroics, no bag-holding"\n\n    def consider(self, b: Briefing) -> Proposal:\n        g = self.genes\n        out: list[Intent] = []\n        for sym, f in b.features.items():\n            held = b.open_positions.get(sym, 0.0) > 0\n\n            if held and (f.trend < g.get("exit_trend_below", 0.0) or f.rsi > g.get("exit_rsi", 80)):\n                out.append(Intent(self.name, sym, "sell", 0.65, 0, (\n                    f"trend broke: trend {f.trend:+.1%}, rsi {f.rsi:.0f}"), dict(g)))\n                continue\n\n            if f.vol > g.get("max_vol", 1.6):\n                continue\n\n            if (f.trend >= g.get("min_trend", 0.005)\n                    and f.slope >= g.get("min_slope", 0.0)\n                    and g.get("rsi_lo", 45) <= f.rsi <= g.get("rsi_hi", 72)\n                    and f.rank_mom >= g.get("min_rank_mom", 0.5)):\n                conv = self.scale(0.40 + 0.30 * f.rank_mom + min(0.25, 8 * max(0.0, f.trend)))\n                out.append(Intent(self.name, sym, "buy", conv, 20, (\n                    f"confirmed trend: ma-spread {f.trend:+.1%}, slope {f.slope:+.2%}, "\n                    f"rsi {f.rsi:.0f} in band"), dict(g)))\n        return self._wrap(b, out)\n\n\nREGISTRY = {\n    "consult_risky": RiskyConsult,\n    "consult_moderate": ModerateConsult,\n    "consult_conservative": ConservativeConsult,\n}\n\n\ndef build_consults(genome: Genome) -> list[BaseConsult]:\n    out = []\n    for name in genome.consults:\n        cls = REGISTRY.get(name)\n        if cls:\n            out.append(cls(genome))\n    return out\n'
_SRC['agents.judges'] = '"""THE JUDGES.\n\nRiskJudge (minor) — reads the three proposals *and* the portfolio, resolves\ndisagreement into position sizes, and vetoes anything that breaks portfolio\nsanity. Its core insight: consensus is information. When three agents that\nthink differently all want the same thing, that\'s a stronger signal than any\none of them shouting.\n\nSuperiorJudge — final authority. Deliberately boring in the trading loop: hard\nlimits and the circuit breaker only. Its real power is in the evolution loop,\nwhere it is the sole writer to the genome.\n"""\nfrom __future__ import annotations\n\nfrom collections import defaultdict\n\nfrom core.genome import Genome\nfrom core.types import Briefing, Order, Proposal, Verdict, Veto\n\n\nclass RiskJudge:\n    name = "risk_judge"\n\n    def __init__(self, genome: Genome):\n        self.g = genome\n        self.genes = genome.genes("risk_judge")\n\n    def rule(self, b: Briefing, proposals: list[Proposal], n_consults: int) -> Verdict:\n        g = self.genes\n        vetoes: list[Veto] = []\n        orders: list[Order] = []\n\n        buys: dict[str, list] = defaultdict(list)\n        sells: dict[str, list] = defaultdict(list)\n        for p in proposals:\n            for it in p.intents:\n                (buys if it.side == "buy" else sells)[it.symbol].append(it)\n\n        # ---- exits first. Always. Freeing risk before adding it is the whole\n        # difference between a portfolio and a collection of hopes.\n        for sym, intents in sells.items():\n            if b.open_positions.get(sym, 0.0) <= 0:\n                continue\n            conv = max(i.conviction for i in intents)\n            share = len(intents) / max(n_consults, 1)\n            score = conv * (0.5 + 0.5 * share)\n            if score >= g.get("sell_conviction_threshold", 0.35):\n                frac = 1.0 if share >= 0.67 else 0.5\n                orders.append(Order(\n                    symbol=sym, side="sell", fraction=frac,\n                    reason_chain=[f"{i.agent}: {i.rationale}" for i in intents],\n                    conviction=conv, agreement=share))\n            else:\n                vetoes.append(Veto(sym, "sell", self.name,\n                                   f"exit conviction {score:.2f} below threshold"))\n\n        selling = {o.symbol for o in orders if o.side == "sell"}\n        regime_scale = float(g.get("regime_scale", {}).get(b.regime, 0.5))\n\n        if regime_scale <= 0.0 and buys:\n            for sym in buys:\n                vetoes.append(Veto(sym, "buy", self.name,\n                                   f"regime \'{b.regime}\' — no new risk"))\n            return Verdict(b.ts, orders, vetoes, 0.0,\n                           f"regime {b.regime}: entries closed", self.name)\n\n        # ---- entries, best-scored first\n        open_count = sum(1 for w in b.open_positions.values() if w > 0)\n        cash_avail = b.equity * max(0.0, b.cash_pct - g.get("cash_floor_pct", 0.05))\n\n        scored = []\n        for sym, intents in buys.items():\n            if sym in selling:\n                vetoes.append(Veto(sym, "buy", self.name, "same-bar exit takes precedence"))\n                continue\n            share = len(intents) / max(n_consults, 1)\n            conv = sum(i.conviction for i in intents) / len(intents)\n            if share >= 0.99:\n                mult = g.get("unanimous_bonus", 1.6)\n            elif share >= 0.66:\n                mult = g.get("two_agree_bonus", 1.2)\n            else:\n                mult = g.get("lone_voice_scale", 0.6)\n            scored.append((conv * mult, sym, intents, share, conv))\n        scored.sort(reverse=True, key=lambda x: x[0])\n\n        max_pos = int(g.get("max_positions", 6))\n        for score, sym, intents, share, conv in scored:\n            if conv < g.get("min_conviction", 0.30):\n                vetoes.append(Veto(sym, "buy", self.name,\n                                   f"conviction {conv:.2f} below floor"))\n                continue\n            held_w = b.open_positions.get(sym, 0.0)\n            if held_w > 0 and not g.get("scale_in_allowed", True):\n                vetoes.append(Veto(sym, "buy", self.name, "already held; scale-in disabled"))\n                continue\n            if held_w <= 0 and open_count >= max_pos:\n                vetoes.append(Veto(sym, "buy", self.name,\n                                   f"position slots full ({open_count}/{max_pos})"))\n                continue\n\n            target = float(g.get("base_size_pct", 0.12)) * score * regime_scale\n            target = min(target, float(g.get("max_position_pct", 0.25)) - held_w)\n            amount = min(target * b.equity, cash_avail)\n            if amount <= 0 or target <= 0:\n                vetoes.append(Veto(sym, "buy", self.name, "no room: size cap or cash floor"))\n                continue\n\n            orders.append(Order(\n                symbol=sym, side="buy", quote_amount=amount,\n                reason_chain=[f"{i.agent}: {i.rationale}" for i in intents],\n                conviction=conv, agreement=share))\n            cash_avail -= amount\n            if held_w <= 0:\n                open_count += 1\n\n        agreement = (sum(o.agreement for o in orders) / len(orders)) if orders else 0.0\n        return Verdict(b.ts, orders, vetoes, agreement,\n                       f"regime {b.regime} (scale {regime_scale:.2f}), "\n                       f"breadth {b.breadth:.0%}", self.name)\n\n\nclass SuperiorJudge:\n    """Final authority. In the trading loop it should rarely intervene — if it\n    overrides the Risk Judge often, that is itself evidence the Risk Judge\'s\n    genes are miscalibrated, and the Researcher is told about it."""\n\n    name = "superior_judge"\n\n    def __init__(self, genome: Genome):\n        self.g = genome\n        self.genes = genome.genes("superior_judge")\n        self.override_count = 0\n        self.overrides: list[str] = []\n\n    def review(self, b: Briefing, v: Verdict, halted: bool) -> Verdict:\n        g = self.genes\n        kept: list[Order] = []\n        vetoes = list(v.vetoes)\n\n        sells = [o for o in v.orders if o.side == "sell"]\n        buys = [o for o in v.orders if o.side == "buy"]\n        kept.extend(sells)  # exits are never blocked. Ever.\n\n        if halted:\n            for o in buys:\n                vetoes.append(Veto(o.symbol, "buy", self.name, "circuit breaker active"))\n                self._log(f"{b.ts} blocked {o.symbol}: circuit breaker")\n            return Verdict(v.ts, kept, vetoes, v.agreement_score,\n                           v.notes + " | HALTED", self.name)\n\n        if b.regime == "crisis" and g.get("block_buys_in_crisis", True):\n            for o in buys:\n                vetoes.append(Veto(o.symbol, "buy", self.name, "crisis regime: capital preservation"))\n                self._log(f"{b.ts} blocked {o.symbol}: crisis regime")\n            return Verdict(v.ts, kept, vetoes, v.agreement_score,\n                           v.notes + " | crisis lockdown", self.name)\n\n        open_count = sum(1 for w in b.open_positions.values() if w > 0)\n        new_positions = 0\n        max_new = int(g.get("max_new_positions_per_bar", 3))\n        hard_max_pos = int(g.get("hard_max_positions", 8))\n        hard_cap = float(g.get("hard_max_position_pct", 0.35))\n        hard_floor = float(g.get("hard_cash_floor_pct", 0.02))\n        spend_budget = b.equity * max(0.0, b.cash_pct - hard_floor)\n\n        for o in buys:\n            held = b.open_positions.get(o.symbol, 0.0)\n            if held <= 0:\n                if open_count + new_positions >= hard_max_pos:\n                    vetoes.append(Veto(o.symbol, "buy", self.name, "hard position-count limit"))\n                    self._log(f"{b.ts} blocked {o.symbol}: hard position limit")\n                    continue\n                if new_positions >= max_new:\n                    vetoes.append(Veto(o.symbol, "buy", self.name, "new-position rate limit"))\n                    self._log(f"{b.ts} blocked {o.symbol}: rate limit")\n                    continue\n            room = (hard_cap - held) * b.equity\n            amt = min(o.quote_amount, room, spend_budget)\n            if amt <= 0:\n                vetoes.append(Veto(o.symbol, "buy", self.name, "hard concentration limit"))\n                self._log(f"{b.ts} blocked {o.symbol}: concentration")\n                continue\n            if amt < o.quote_amount * 0.999:\n                self._log(f"{b.ts} trimmed {o.symbol}: {o.quote_amount:.0f} -> {amt:.0f}")\n            o.quote_amount = amt\n            o.reason_chain.append(f"{self.name}: approved (cap-checked)")\n            kept.append(o)\n            spend_budget -= amt\n            if held <= 0:\n                new_positions += 1\n\n        return Verdict(v.ts, kept, vetoes, v.agreement_score, v.notes, self.name)\n\n    def _log(self, msg: str) -> None:\n        self.override_count += 1\n        if len(self.overrides) < 500:\n            self.overrides.append(msg)\n\n\ndef flag_hard_call(orders: list[Order], just_halted: bool, overrides_this_bar: int,\n                   low_agreement_threshold: float = 0.4,\n                   nav: float | None = None,\n                   min_size_pct: float = 0.0) -> dict[str, Any]:\n    """Cheap, deterministic triage for which bars deserve a slower second look.\n\n    This is not a verdict and it changes nothing the Trader executes -- it only\n    labels bars where the machinery disagreed with itself (Superior Judge\n    overrode the Risk Judge), acted on thin consensus in its single biggest bet\n    (a lone-voice buy that is also the bar\'s highest-conviction order), or did\n    something drastic (the circuit breaker just tripped). That label is the\n    "flag hard calls" half of the LLM-backed-consult plan in AGENTS.md item 4:\n    pick out which bars are worth spending a slower, reasoned opinion on,\n    before any such opinion exists to spend. The other half -- actually\n    consulting on a flagged bar and feeding a verdict back in -- is not built\n    yet; this only marks the candidates.\n\n    The low-agreement trigger was measured (2026-08-17,\n    `evotrader_bundle.py hard-calls`) against a bar-level aggregate\n    (`agreement_score`, the mean across every order that bar) and found to\n    fire on 38.6% of bars -- almost entirely "exactly one of three consults\n    proposed *a* buy that bar", a pattern the Risk Judge already prices in via\n    `lone_voice_scale`, not a rare event. A first narrowing read each order\'s\n    own `agreement` field instead and only flagged a lone-voice buy when it\n    was *also* the bar\'s single highest-conviction buy order -- but that\n    measured *worse* (52.0%, `runs/2026-08-17-1553-hard-call-trigger-narrowing.md`):\n    lone-voice and highest-conviction-that-bar turn out to be strongly\n    correlated here, not independent, because most bars with any buy at all\n    have exactly one. A second narrowing required the lone-voice buy be the\n    *only* order the bar produced at all -- no other buy, no sell -- and that\n    worked (24.4%, `runs/2026-08-17-1850-hard-call-solo-bar-narrowing.md`):\n    "the whole council went quiet except one loud voice" vs. "one of several\n    independent picks that bar happened to be lone-voice".\n\n    This version adds a third, independent axis on top of the solo-bar\n    requirement rather than replacing it: `min_size_pct` gates on how much of\n    the account\'s equity the lone-voice buy actually commits. A solo bar with\n    a token-sized position is a different claim from a solo bar betting a\n    real fraction of the book on one weak-consensus signal -- only the latter\n    is the kind of decision worth a slower second look. When `min_size_pct`\n    is 0.0 (the default) this axis is off and behavior is identical to the\n    solo-bar-only version; a caller opts in by passing both `nav` (the bar\'s\n    portfolio equity, already computed by `Council.tick` before this is\n    called) and a positive `min_size_pct`. Measured against the real live\n    champion (2026-08-17, `evotrader_bundle.py hard-calls`): of the 253 solo\n    lone-voice bars on a full-history replay, position sizes ranged from a\n    fraction of a percent of equity up to 24.8%, with no natural break -- a\n    continuous spread, not two clusters. `min_size_pct=0.10` is the wired\n    default because it cuts this trigger\'s own contribution from 18.3% of all\n    bars to 3.5% (253 -> 48 bars) while still catching every solo bet that\n    actually risks a meaningful slice of the account, bringing the combined\n    flag rate to ~9.6% of bars -- close to the circuit_breaker +\n    superior_override-only floor (~6.1%) instead of nearly 4x it.\n    """\n    reasons: list[str] = []\n    if just_halted:\n        reasons.append("circuit breaker tripped this bar")\n    if overrides_this_bar > 0:\n        reasons.append(f"superior_judge intervened on {overrides_this_bar} order(s)")\n    buys = [o for o in orders if o.side == "buy"]\n    if buys and len(orders) == 1:\n        leader = buys[0]\n        if leader.agreement < low_agreement_threshold:\n            size_pct = (leader.quote_amount / nav) if nav else 0.0\n            if min_size_pct <= 0.0 or size_pct >= min_size_pct:\n                detail = f", {size_pct:.1%} of equity" if min_size_pct > 0.0 else ""\n                reasons.append(\n                    f"lone-voice buy on {leader.symbol} (agreement {leader.agreement:.2f}) "\n                    f"is the only order the bar produced ({leader.conviction:.2f} conviction"\n                    f"{detail})")\n    return {"is_hard_call": bool(reasons), "reasons": reasons}\n\n\ndef summarize_hard_calls(decision_log: list[dict[str, Any]]) -> dict[str, Any]:\n    """Aggregate `flag_hard_call` output across a decision log (a live\n    journal\'s per-tick decisions, or a backtest\'s `decision_log`) into counts\n    a human can read in one screen: how often it fires, and on which of the\n    three triggers. Read-only — takes an already-built log, never a genome or\n    live state, so it cannot touch anything by construction.\n\n    This exists to answer "does this actually flag any real bars?" without\n    waiting on one live tick at a time: a full-history backtest already runs\n    every bar through the same `flag_hard_call` call a live tick would, so it\n    gives the same answer many bars at once.\n    """\n    n = len(decision_log)\n    flagged = [d for d in decision_log if d.get("hard_call", {}).get("is_hard_call")]\n    by_category = {"circuit_breaker": 0, "superior_override": 0, "low_agreement_buy": 0}\n    for d in flagged:\n        for r in d["hard_call"]["reasons"]:\n            if r.startswith("circuit breaker"):\n                by_category["circuit_breaker"] += 1\n            elif r.startswith("superior_judge"):\n                by_category["superior_override"] += 1\n            elif r.startswith("lone-voice buy"):\n                by_category["low_agreement_buy"] += 1\n    return {\n        "n_bars": n,\n        "n_flagged": len(flagged),\n        "flag_rate": (len(flagged) / n) if n else 0.0,\n        "by_category": by_category,\n        "flagged": [{"ts": d.get("ts"), "reasons": d["hard_call"]["reasons"]}\n                    for d in flagged],\n    }\n\n\ndef pending_hard_call_reviews(journal: list[dict[str, Any]],\n                              reviews: list[dict[str, Any]]) -> list[dict[str, Any]]:\n    """Which flagged live ticks still have no recorded review.\n\n    This is the first piece of the "review after the fact" half of AGENTS.md\n    item 4\'s design (b): flag_hard_call already marks candidate bars\n    (additive, computed after execution); this is a pure set difference\n    between `LiveAccount.journal` (what actually happened) and\n    `LiveAccount.hard_call_reviews` (verdicts a later scheduled session wrote\n    back after reasoning about a flagged bar) -- matched by `tick`, the\n    journal\'s own stable id. Design (b) over (a) because the measured flag\n    rate (~9.6% as of 2026-08-17, `evotrader_bundle.py hard-calls`) is low\n    enough that a scheduled session can plausibly look at every flagged bar\n    without it becoming the normal path, and because a live daily tick only\n    produces at most one candidate a day -- (a)\'s stop-before-execution\n    split isn\'t needed to keep up with that rate.\n\n    Read-only: takes two already-built lists, never state itself, so it\n    cannot write anything by construction. Nothing yet calls this outside\n    the `review-hard-calls` CLI command -- no live journal entry has ever\n    actually flagged (`is_hard_call: true`) as of this writing, so this is\n    infrastructure ahead of its first real case, not a response to one.\n    """\n    reviewed_ticks = {r["tick"] for r in reviews}\n    pending = []\n    for entry in journal:\n        hc = (entry.get("decision") or {}).get("hard_call") or {}\n        if hc.get("is_hard_call") and entry.get("tick") not in reviewed_ticks:\n            pending.append({\n                "tick": entry.get("tick"),\n                "bar": entry.get("bar"),\n                "reasons": hc.get("reasons", []),\n            })\n    return pending\n'
_SRC['agents.trader'] = '"""GUARDIAN + TRADER.\n\nGuardian runs *before* the council every bar and issues mandatory exits: stop\nloss, trailing stop, take profit, max holding period. These are not opinions\nand no judge can veto them. Consults are optimists by construction; something\nin the system has to be unconditionally willing to sell.\n\nTrader has no discretion at all. It takes approved orders and puts them\nthrough the broker at the next open. Keeping judgement out of execution means\na bad fill is a broker-model bug, never a strategy question.\n"""\nfrom __future__ import annotations\n\nfrom core.genome import Genome\nfrom core.portfolio import PaperBroker\nfrom core.types import Order, Verdict\n\n\nclass Guardian:\n    name = "guardian"\n\n    def __init__(self, genome: Genome):\n        self.r = genome.risk\n\n    def forced_exits(self, broker: PaperBroker, prices: dict[str, float]) -> list[Order]:\n        out: list[Order] = []\n        stop = float(self.r.get("stop_loss", -0.12))\n        trail = float(self.r.get("trailing_stop", -0.15))\n        tp = float(self.r.get("take_profit", 0.35))\n        max_bars = int(self.r.get("max_bars_held", 60))\n        min_bars = int(self.r.get("min_bars_held", 1))\n\n        for sym, pos in list(broker.positions.items()):\n            if not pos.is_open:\n                continue\n            px = prices.get(sym)\n            if not px or pos.avg_cost <= 0:\n                continue\n            if pos.bars_held < min_bars:\n                continue\n            pnl = px / pos.avg_cost - 1\n            from_peak = (px / pos.peak_price - 1) if pos.peak_price > 0 else 0.0\n\n            reason = None\n            if pnl <= stop:\n                reason = f"stop loss hit ({pnl:+.1%})"\n            elif from_peak <= trail and pnl > 0:\n                reason = f"trailing stop ({from_peak:+.1%} off peak, locking {pnl:+.1%})"\n            elif pnl >= tp:\n                reason = f"take profit ({pnl:+.1%})"\n            elif pos.bars_held >= max_bars:\n                reason = f"time stop ({pos.bars_held} bars, {pnl:+.1%})"\n\n            if reason:\n                out.append(Order(symbol=sym, side="sell", fraction=1.0,\n                                 reason_chain=[f"{self.name}: {reason}"],\n                                 conviction=1.0, agreement=1.0))\n        return out\n\n\nclass Trader:\n    name = "trader"\n\n    def __init__(self, broker: PaperBroker):\n        self.broker = broker\n        self.executed = 0\n        self.rejected = 0\n\n    def execute(self, ts: str, orders: list[Order],\n                fill_prices: dict[str, float]) -> list[dict]:\n        log: list[dict] = []\n        # sells first — they fund the buys\n        for o in sorted(orders, key=lambda x: 0 if x.side == "sell" else 1):\n            px = fill_prices.get(o.symbol)\n            if px is None:\n                self.rejected += 1\n                log.append({"symbol": o.symbol, "side": o.side, "status": "no_price"})\n                continue\n            reason = " | ".join(o.reason_chain[-2:])\n            agents = tuple(sorted({r.split(":")[0].strip() for r in o.reason_chain\n                                   if ":" in r and r.split(":")[0].strip().startswith("consult")}))\n            f = (self.broker.sell(ts, o.symbol, o.fraction, px, reason) if o.side == "sell"\n                 else self.broker.buy(ts, o.symbol, o.quote_amount, px, reason, agents))\n            if f is None:\n                self.rejected += 1\n                log.append({"symbol": o.symbol, "side": o.side, "status": "rejected"})\n            else:\n                self.executed += 1\n                log.append({"symbol": o.symbol, "side": o.side, "status": "filled",\n                            "qty": f.qty, "price": f.price, "reason": reason})\n        return log\n'
_SRC['agents.researcher'] = '"""RESEARCHER — proposes changes to the roster.\n\nTwo sources of hypotheses, deliberately mixed:\n\n1. **Diagnosis-driven.** Read the ledger, find where money actually leaked,\n   propose a change aimed at that leak. High prior of being right, low\n   novelty — it can only fix problems that have already cost money.\n\n2. **Blind perturbation.** Random moves in gene space. Low hit rate, but it is\n   the only source of ideas nobody thought of. Every genuinely surprising\n   improvement in this system will come from here.\n\nPer Burk\'s instruction, the hypothesis space is generated from the system\'s own\ndata and from general principles — not by copying human traders. Most humans\nlose money; imitating them imports their losses along with their style.\n\nThe Researcher has no authority. It writes proposals. The Evaluator measures\nthem and the Superior Judge decides. It cannot touch the constitution, the\nbroker, or the fitness function.\n"""\nfrom __future__ import annotations\n\nimport random\nfrom collections import defaultdict\nfrom typing import Any\n\nfrom core.genome import Genome\nfrom core.types import Mutation\n\n# The mutable surface. Anything not listed here cannot be changed by evolution\n# — an allowlist, not a denylist, so a new gene is inert until someone\n# deliberately opens it up.\nGENE_SPACE: dict[str, tuple[float, float, str]] = {\n    "risk.stop_loss": (-0.45, -0.04, "float"),\n    "risk.trailing_stop": (-0.45, -0.05, "float"),\n    "risk.take_profit": (0.06, 1.50, "float"),\n    "risk.max_bars_held": (5, 250, "int"),\n\n    "agents.consult_risky.genes.min_breakout": (-0.15, 0.01, "float"),\n    "agents.consult_risky.genes.min_rank_mom": (0.30, 0.95, "float"),\n    "agents.consult_risky.genes.rsi_max": (55.0, 95.0, "float"),\n    "agents.consult_risky.genes.exit_rsi": (60.0, 99.0, "float"),\n    "agents.consult_risky.genes.exit_trend_below": (-0.25, 0.02, "float"),\n    "agents.consult_risky.genes.conviction_scale": (0.3, 2.0, "float"),\n\n    "agents.consult_moderate.genes.min_trend": (-0.03, 0.08, "float"),\n    "agents.consult_moderate.genes.rsi_lo": (25.0, 60.0, "float"),\n    "agents.consult_moderate.genes.rsi_hi": (60.0, 92.0, "float"),\n    "agents.consult_moderate.genes.min_rank_mom": (0.20, 0.90, "float"),\n    "agents.consult_moderate.genes.max_vol": (0.5, 3.5, "float"),\n    "agents.consult_moderate.genes.exit_trend_below": (-0.25, 0.03, "float"),\n    "agents.consult_moderate.genes.exit_rsi": (60.0, 99.0, "float"),\n    "agents.consult_moderate.genes.conviction_scale": (0.3, 2.0, "float"),\n\n    "agents.consult_conservative.genes.rsi_buy_below": (15.0, 50.0, "float"),\n    "agents.consult_conservative.genes.z_buy_below": (-3.0, 0.2, "float"),\n    "agents.consult_conservative.genes.max_vol": (0.4, 3.0, "float"),\n    "agents.consult_conservative.genes.max_dd_from_high": (-0.75, -0.05, "float"),\n    "agents.consult_conservative.genes.exit_rsi": (50.0, 95.0, "float"),\n    "agents.consult_conservative.genes.conviction_scale": (0.3, 2.0, "float"),\n    "agents.consult_conservative.genes.min_trend": (-0.15, 0.05, "float"),\n\n    "agents.risk_judge.genes.base_size_pct": (0.03, 0.35, "float"),\n    "agents.risk_judge.genes.unanimous_bonus": (1.0, 3.0, "float"),\n    "agents.risk_judge.genes.two_agree_bonus": (0.6, 2.2, "float"),\n    "agents.risk_judge.genes.lone_voice_scale": (0.0, 1.5, "float"),\n    "agents.risk_judge.genes.min_conviction": (0.05, 0.75, "float"),\n    "agents.risk_judge.genes.max_positions": (2, 10, "int"),\n    "agents.risk_judge.genes.max_position_pct": (0.05, 0.34, "float"),\n    "agents.risk_judge.genes.cash_floor_pct": (0.0, 0.5, "float"),\n    "agents.risk_judge.genes.sell_conviction_threshold": (0.1, 0.9, "float"),\n\n    "agents.analyst.genes.trend_fast": (3, 30, "int"),\n    "agents.analyst.genes.trend_slow": (25, 150, "int"),\n    "agents.analyst.genes.rsi_len": (5, 40, "int"),\n    "agents.analyst.genes.breakout_len": (5, 90, "int"),\n    "agents.analyst.genes.regime_ma": (20, 200, "int"),\n\n    "agents.superior_judge.genes.max_new_positions_per_bar": (1, 6, "int"),\n}\n\nREGIME_KEYS = ["bull", "chop", "bear", "crisis"]\n\n\ndef _get_path(d: dict, path: str) -> Any:\n    node: Any = d\n    for p in path.split("."):\n        if not isinstance(node, dict) or p not in node:\n            return None\n        node = node[p]\n    return node\n\n\ndef _clamp(v, lo, hi, kind):\n    v = max(lo, min(hi, v))\n    return int(round(v)) if kind == "int" else round(float(v), 4)\n\n\ndef diagnose(result: dict[str, Any]) -> dict[str, Any]:\n    """Where did the money actually go? This is the Researcher\'s evidence base."""\n    trades = result.get("closed_trades", [])\n    stats = result.get("stats", {})\n    pnl_by_exit: dict[str, float] = defaultdict(float)\n    n_by_exit: dict[str, int] = defaultdict(int)\n    pnl_by_entry: dict[str, float] = defaultdict(float)\n    n_by_entry: dict[str, int] = defaultdict(int)\n\n    for t in trades:\n        who = str(t.get("exit_reason", "")).split(":")[0].strip()[:30] or "unknown"\n        pnl_by_exit[who] += t.get("pnl", 0.0)\n        n_by_exit[who] += 1\n        for a in (t.get("entry_agents") or ["unattributed"]):\n            pnl_by_entry[a] += t.get("pnl", 0.0)\n            n_by_entry[a] += 1\n\n    stop_trades = [t for t in trades if "stop loss" in str(t.get("exit_reason", ""))]\n    tp_trades = [t for t in trades if "take profit" in str(t.get("exit_reason", ""))]\n    time_trades = [t for t in trades if "time stop" in str(t.get("exit_reason", ""))]\n\n    return {\n        "pnl_by_exit": dict(pnl_by_exit), "n_by_exit": dict(n_by_exit),\n        "pnl_by_entry": dict(pnl_by_entry), "n_by_entry": dict(n_by_entry),\n        "stop_share": len(stop_trades) / len(trades) if trades else 0.0,\n        "stop_pnl": sum(t["pnl"] for t in stop_trades),\n        "tp_share": len(tp_trades) / len(trades) if trades else 0.0,\n        "time_share": len(time_trades) / len(trades) if trades else 0.0,\n        "avg_bars_held": stats.get("avg_bars_held", 0.0),\n        "trades": len(trades),\n        "win_rate": stats.get("win_rate", 0.0),\n        "turnover": stats.get("turnover_annual", 0.0),\n        "halt_count": stats.get("halt_count", 0),\n        "superior_overrides": result.get("superior_overrides", 0),\n    }\n\n\nclass Researcher:\n    name = "researcher"\n\n    def __init__(self, seed: int | None = None):\n        self.rng = random.Random(seed)\n\n    # -- 1. diagnosis-driven ----------------------------------------------\n    def from_diagnosis(self, g: Genome, d: dict[str, Any]) -> list[Mutation]:\n        out: list[Mutation] = []\n\n        # Stops that fire often AND lose money are usually sitting inside the\n        # asset\'s normal noise band, not outside it.\n        if d["stop_share"] > 0.15 and d["stop_pnl"] < 0:\n            cur = g.risk.get("stop_loss", -0.12)\n            out.append(Mutation(\n                kind="tune", target="risk.stop_loss",\n                patch={"risk.stop_loss": _clamp(cur * 1.6, *GENE_SPACE["risk.stop_loss"][:2],\n                                                GENE_SPACE["risk.stop_loss"][2])},\n                hypothesis=(f"{d[\'stop_share\']:.0%} of exits are stop-losses and they lost "\n                            f"{d[\'stop_pnl\']:.0f} — the stop is inside daily noise; widen it")))\n\n        # Time stops firing a lot means the holding period is fighting the\n        # signal\'s natural horizon.\n        if d["time_share"] > 0.25:\n            cur = g.risk.get("max_bars_held", 60)\n            out.append(Mutation(\n                kind="tune", target="risk.max_bars_held",\n                patch={"risk.max_bars_held": _clamp(cur * 2, 5, 250, "int")},\n                hypothesis=f"{d[\'time_share\']:.0%} of exits are time stops — horizon too short"))\n\n        # An entry agent that is reliably net-negative over enough trades is\n        # not adding a view, it\'s adding losses.\n        for agent, pnl in d["pnl_by_entry"].items():\n            n = d["n_by_entry"].get(agent, 0)\n            if agent.startswith("consult") and n >= 25 and pnl < 0:\n                cur = g.gene(agent, "conviction_scale", 1.0)\n                out.append(Mutation(\n                    kind="reweight", target=f"agents.{agent}.genes.conviction_scale",\n                    patch={f"agents.{agent}.genes.conviction_scale": _clamp(cur * 0.6, 0.3, 2.0, "float")},\n                    hypothesis=f"{agent} entries lost {pnl:.0f} over {n} trades — turn it down"))\n                out.append(Mutation(\n                    kind="remove_agent", target=agent,\n                    patch={f"agents.{agent}.enabled": False},\n                    hypothesis=f"{agent} entries lost {pnl:.0f} over {n} trades — try removing it",\n                    complexity_delta=-1 - len(g.genes(agent))))\n\n        # The Superior Judge should be a rubber stamp. If it\'s constantly\n        # overriding, the Risk Judge is sizing beyond the hard limits.\n        if d["superior_overrides"] > max(30, d["trades"] * 0.4):\n            cur = g.gene("risk_judge", "base_size_pct", 0.12)\n            out.append(Mutation(\n                kind="tune", target="agents.risk_judge.genes.base_size_pct",\n                patch={"agents.risk_judge.genes.base_size_pct": _clamp(cur * 0.7, 0.03, 0.35, "float")},\n                hypothesis=(f"superior judge intervened {d[\'superior_overrides\']} times — "\n                            "the risk judge is sizing past the hard caps")))\n\n        # Repeated circuit-breaker trips = too much risk on at once.\n        if d["halt_count"] >= 2:\n            cur = g.gene("risk_judge", "max_position_pct", 0.25)\n            out.append(Mutation(\n                kind="tune", target="agents.risk_judge.genes.max_position_pct",\n                patch={"agents.risk_judge.genes.max_position_pct": _clamp(cur * 0.7, 0.05, 0.34, "float")},\n                hypothesis=f"circuit breaker tripped {d[\'halt_count\']}x — concentration too high"))\n\n        # Very low trade count starves the evidence gate.\n        if d["trades"] < 40:\n            cur = g.gene("risk_judge", "min_conviction", 0.30)\n            out.append(Mutation(\n                kind="tune", target="agents.risk_judge.genes.min_conviction",\n                patch={"agents.risk_judge.genes.min_conviction": _clamp(cur * 0.7, 0.05, 0.75, "float")},\n                hypothesis=f"only {d[\'trades\']} trades — too selective to measure"))\n\n        return out\n\n    # -- 2. blind search ---------------------------------------------------\n    def perturb(self, g: Genome, n: int = 12, n_genes: int = 2,\n                boldness: float = 0.0) -> list[Mutation]:\n        """`boldness` rises with how long the champion has gone unbeaten.\n\n        A search that keeps failing in the same neighbourhood should widen its\n        steps, not keep re-sampling the same basin — the local hill has been\n        climbed, and what\'s left is either further away or isn\'t there.\n        """\n        out: list[Mutation] = []\n        paths = list(GENE_SPACE)\n        jump_p = min(0.75, 0.2 + 0.12 * boldness)\n        spread = 1.0 + 0.35 * boldness\n        genes_per = min(len(paths), n_genes + int(boldness // 2))\n        for _ in range(n):\n            picks = self.rng.sample(paths, k=min(genes_per, len(paths)))\n            patch: dict[str, Any] = {}\n            desc = []\n            for path in picks:\n                lo, hi, kind = GENE_SPACE[path]\n                cur = _get_path(g.data, path)\n                if cur is None:\n                    continue\n                # log-ish multiplicative jitter, plus an occasional big jump so\n                # search isn\'t trapped in the basin around the seed\n                if self.rng.random() < jump_p:\n                    nv = self.rng.uniform(lo, hi)\n                else:\n                    nv = (cur * self.rng.uniform(1 - 0.4 * spread, 1 + 0.6 * spread)\n                          + self.rng.gauss(0, abs(hi - lo) * 0.05 * spread))\n                nv = _clamp(nv, lo, hi, kind)\n                if nv == cur:\n                    continue\n                patch[path] = nv\n                desc.append(f"{path.split(\'.\')[-1]} {cur}->{nv}")\n            if patch:\n                out.append(Mutation(kind="tune", target="+".join(sorted(patch)),\n                                    patch=patch,\n                                    hypothesis="blind search: " + ", ".join(desc)))\n        return out\n\n    # -- 3. structural -----------------------------------------------------\n    def structural(self, g: Genome) -> list[Mutation]:\n        out: list[Mutation] = []\n        for agent in ("consult_risky", "consult_moderate", "consult_conservative"):\n            if g.enabled(agent):\n                out.append(Mutation(\n                    kind="remove_agent", target=agent,\n                    patch={f"agents.{agent}.enabled": False},\n                    hypothesis=f"is {agent} carrying its weight, or just adding noise?",\n                    complexity_delta=-1 - len(g.genes(agent))))\n            else:\n                out.append(Mutation(\n                    kind="add_agent", target=agent,\n                    patch={f"agents.{agent}.enabled": True},\n                    hypothesis=f"conditions may have changed — try {agent} again",\n                    complexity_delta=1 + len(g.genes(agent))))\n\n        # regime scaling is where most of the risk control actually lives\n        cur = dict(g.gene("risk_judge", "regime_scale", {}))\n        for k in REGIME_KEYS:\n            if k not in cur:\n                continue\n            for mult in (0.5, 1.5):\n                nv = round(min(1.5, max(0.0, cur[k] * mult)), 3)\n                if nv != cur[k]:\n                    out.append(Mutation(\n                        kind="tune", target=f"regime_scale.{k}",\n                        patch={f"agents.risk_judge.genes.regime_scale.{k}": nv},\n                        hypothesis=f"size {\'up\' if mult > 1 else \'down\'} in \'{k}\' regime: {cur[k]} -> {nv}"))\n\n        return out\n\n    @staticmethod\n    def key(m: Mutation) -> tuple:\n        """Identity of a proposal — the patch itself, not its prose."""\n        return tuple((k, str(v)) for k, v in sorted(m.patch.items(), key=lambda kv: kv[0]))\n\n    def propose(self, g: Genome, diagnostics: dict[str, Any], n_blind: int = 14,\n                exclude: set | None = None, boldness: float = 0.0) -> list[Mutation]:\n        """`exclude` is the set of proposal keys already ruled out against this\n        champion. Without it the diagnosis-driven and structural proposals are\n        deterministic given the champion, so an unbeaten champion gets the\n        identical losing candidate re-tested every single generation — four\n        generations of this project burned twelve backtests re-rejecting one\n        idea before the memory was added."""\n        exclude = exclude or set()\n        props = self.from_diagnosis(g, diagnostics)\n        props += self.structural(g)\n        props += self.perturb(g, n=n_blind, boldness=boldness)\n\n        seen, uniq = set(), []\n        for m in props:\n            k = self.key(m)\n            if k in seen or k in exclude:\n                continue\n            seen.add(k)\n            uniq.append(m)\n        return uniq\n'
_SRC['loop'] = ''
_SRC['loop.engine'] = '"""The decision cycle, and the backtest that replays it over history.\n\nOne tick:\n    mark portfolio  ->  Guardian forced exits  ->  Analyst briefing\n    ->  3 Consults  ->  Risk Judge  ->  Superior Judge  ->  Trader\n    ->  fills at the NEXT bar\'s open\n\nThe same function runs a 4-year backtest and (later) a single live bar. There\nis exactly one code path for "what does the system do right now", which is the\nonly way a live run can ever be expected to match its own backtest.\n"""\nfrom __future__ import annotations\n\nimport json\nimport math\nimport os\nfrom dataclasses import asdict\nfrom typing import Any\n\nimport numpy as np\n\nfrom agents.analyst import Analyst\nfrom agents.consults import build_consults\nfrom agents.judges import RiskJudge, SuperiorJudge, flag_hard_call\nfrom agents.trader import Guardian, Trader\nfrom core import market\nfrom core.genome import Genome\nfrom core.market import Replay\nfrom core.portfolio import PaperBroker\nfrom core.types import Order, Verdict\nfrom constitution import (CIRCUIT_BREAKER_DD, CIRCUIT_BREAKER_COOLDOWN,\n                          CIRCUIT_BREAKER_FLATTEN, fitness)\n\n\nclass Council:\n    """The whole roster, assembled from a genome."""\n\n    def __init__(self, genome: Genome, broker: PaperBroker):\n        self.genome = genome\n        self.broker = broker\n        self.analyst = Analyst(genome)\n        self.consults = build_consults(genome)\n        self.risk_judge = RiskJudge(genome)\n        self.superior = SuperiorJudge(genome)\n        self.guardian = Guardian(genome)\n        self.trader = Trader(broker)\n        self.decision_log: list[dict[str, Any]] = []\n\n    def tick(self, window, prices: dict[str, float], fill_prices: dict[str, float],\n             log_detail: bool = True) -> None:\n        b = self.broker\n        ts = str(window.ts)\n        nav = b.mark(ts, prices, dd_halt=CIRCUIT_BREAKER_DD,\n                     cooldown=CIRCUIT_BREAKER_COOLDOWN)\n\n        forced = self.guardian.forced_exits(b, prices)\n        if b.just_halted and CIRCUIT_BREAKER_FLATTEN:\n            # A breaker that freezes new entries but keeps the existing book is\n            # theatre — the damage is already in the positions you hold.\n            held = {o.symbol for o in forced}\n            for sym, pos in list(b.positions.items()):\n                if pos.is_open and sym not in held:\n                    forced.append(Order(symbol=sym, side="sell", fraction=1.0,\n                                        reason_chain=["circuit_breaker: flatten book"],\n                                        conviction=1.0, agreement=1.0))\n        if forced:\n            self.trader.execute(ts, forced, fill_prices)\n\n        weights = {s: b.position_weight(s, prices) for s in b.positions if b.positions[s].is_open}\n        briefing = self.analyst.brief(window, nav, b.cash, weights)\n        proposals = [c.consider(briefing) for c in self.consults]\n        verdict = self.risk_judge.rule(briefing, proposals, len(self.consults))\n        overrides_before = self.superior.override_count\n        final: Verdict = self.superior.review(briefing, verdict, b.halted)\n        overrides_this_bar = self.superior.override_count - overrides_before\n        fills = self.trader.execute(ts, final.orders, fill_prices)\n\n        if log_detail and (fills or forced or final.vetoes):\n            self.decision_log.append({\n                "ts": ts, "nav": nav, "regime": briefing.regime,\n                "breadth": briefing.breadth, "cash_pct": briefing.cash_pct,\n                "proposals": {p.agent: [\n                    {"symbol": i.symbol, "side": i.side,\n                     "conviction": round(i.conviction, 3), "why": i.rationale}\n                    for i in p.intents] for p in proposals},\n                "forced_exits": [{"symbol": o.symbol, "why": o.reason_chain[0]} for o in forced],\n                "orders": [{"symbol": o.symbol, "side": o.side,\n                            "amount": round(o.quote_amount, 2), "fraction": o.fraction,\n                            "agreement": round(o.agreement, 2),\n                            "why": o.reason_chain} for o in final.orders],\n                "vetoes": [asdict(v) for v in final.vetoes[:12]],\n                "fills": fills,\n                "notes": final.notes,\n                "hard_call": flag_hard_call(final.orders, b.just_halted, overrides_this_bar,\n                                            nav=nav, min_size_pct=0.10),\n            })\n\n\ndef benchmark_buy_hold(replay: Replay, symbols: list[str], start: int, end: int,\n                       cash: float, bars_per_year: float = 365.25) -> dict[str, Any]:\n    """Equal-weight buy-and-hold. The honest bar to clear — beating your own\n    ancestors means nothing if a lazy index beats you both."""\n    usable = [s for s in symbols if replay.next_open(s, start) not in (None, 0)]\n    if not usable:\n        return {}\n    per = cash / len(usable)\n    qty = {s: per / replay.next_open(s, start) for s in usable}\n    navs = []\n    for i in range(start + 1, end):\n        v = 0.0\n        for s in usable:\n            px = replay.close_at(s, i)\n            if px:\n                v += qty[s] * px\n        navs.append(v)\n    if len(navs) < 3:\n        return {}\n    import numpy as np\n    a = np.array(navs)\n    rets = np.diff(a) / np.maximum(a[:-1], 1e-9)\n    peaks = np.maximum.accumulate(a)\n    import math\n    vol = float(np.std(rets, ddof=1)) * math.sqrt(bars_per_year)\n    return {\n        "total_return": float(a[-1] / a[0] - 1),\n        "max_dd": float(np.min(a / peaks - 1)),\n        "sharpe": float(np.mean(rets) * bars_per_year / vol) if vol > 1e-9 else 0.0,\n        "end_nav": float(a[-1]), "start_nav": float(a[0]),\n    }\n\n\ndef pairwise_correlation_stats(rets: dict[str, np.ndarray],\n                               threshold: float = 0.5) -> dict[str, Any]:\n    """Every pairwise Pearson correlation across a set of return series, summarised.\n\n    Originally built to answer a structural question the live mechanism at\n    the time (agents.judges.RiskJudge._correlation_scale, a gene that only\n    ever compared a *new* buy against symbols already held, on the\n    reasoning that unheld correlation can\'t hurt a portfolio that isn\'t\n    exposed to it) never asked. That gene has since been removed as dead\n    weight (AGENTS.md item 3, 2026-08-20) once the evidence this function\n    helped gather settled on "drop". This function stays: it looks at the\n    whole universe\'s pairwise structure -- whether there\'s a tightly\n    correlated cluster, or a correlation regime (crisis contagion) a\n    held-vs-candidate check would only catch after a position is already\n    open -- independent of any genome, still useful for any future\n    concentration/diversification question. Read-only: takes\n    already-sliced return arrays, never a genome, broker, or replay -- it\n    cannot touch anything by construction.\n\n    A symbol with too little history or a near-zero-variance return series\n    over the window is silently dropped from the pair count rather than\n    raising -- fail toward nothing to report.\n    """\n    syms = sorted(rets.keys())\n    pairs: list[float] = []\n    for i, a in enumerate(syms):\n        ra = rets[a]\n        for b in syms[i + 1:]:\n            rb = rets[b]\n            n = min(len(ra), len(rb))\n            if n < 5:\n                continue\n            xa, xb = ra[-n:], rb[-n:]\n            if not (np.all(np.isfinite(xa)) and np.all(np.isfinite(xb))):\n                continue\n            sa, sb = np.std(xa), np.std(xb)\n            if sa < 1e-12 or sb < 1e-12:\n                continue\n            c = float(np.corrcoef(xa, xb)[0, 1])\n            if np.isfinite(c):\n                pairs.append(c)\n    if len(syms) < 3 or not pairs:\n        return {"error": "fewer than 3 usable symbols or no valid pairs",\n                "n_symbols": len(syms), "n_pairs": len(pairs)}\n    arr = np.array(pairs)\n    return {\n        "n_symbols": len(syms),\n        "n_pairs": int(len(arr)),\n        "mean_corr": float(np.mean(arr)),\n        "median_corr": float(np.median(arr)),\n        "min_corr": float(np.min(arr)),\n        "max_corr": float(np.max(arr)),\n        "frac_above_threshold": float(np.mean(arr >= threshold)),\n        "threshold": threshold,\n    }\n\n\ndef holding_mask(closed_trades: list[dict], open_positions: list[dict],\n                ts_index: dict[str, int], n: int) -> dict[str, np.ndarray]:\n    """Boolean per-bar mask of which symbols the account actually held,\n    reconstructed purely from closed_trades\' entry/exit timestamps plus\n    any positions still open at the end of the replay window -- no genome\n    or broker access needed, just run_backtest\'s own returned records.\n\n    Exists to answer the follow-up `correlation-universe` left open:\n    raw universe-wide pairwise correlation (what `pairwise_correlation_\n    stats` measures across every symbol) is not the same question as\n    portfolio-realized correlation -- whether the symbols the champion\n    actually holds *together* happen to be more or less correlated than\n    the universe at large. This mask is the bridge: index it by bar to\n    get the held set, then feed that subset into the same\n    `pairwise_correlation_stats` function.\n\n    Bar i counts as held for [entry_i, exit_i) -- half-open, matching\n    core.portfolio\'s own fill-to-fill convention (a position is open from\n    the bar it fills on up to, not including, the bar the closing fill\n    lands on). A timestamp missing from ts_index is silently skipped\n    rather than raising -- the same fail-toward-nothing-to-report\n    convention `pairwise_correlation_stats` already uses for degenerate\n    input.\n    """\n    mask: dict[str, np.ndarray] = {}\n\n    def mark(symbol, entry_ts, exit_i):\n        entry_i = ts_index.get(entry_ts)\n        if entry_i is None or symbol is None:\n            return\n        arr = mask.setdefault(symbol, np.zeros(n, dtype=bool))\n        lo, hi = max(0, entry_i), min(n, exit_i)\n        if hi > lo:\n            arr[lo:hi] = True\n\n    for t in closed_trades:\n        exit_i = ts_index.get(t.get("exit_ts"))\n        if exit_i is not None:\n            mark(t.get("symbol"), t.get("entry_ts"), exit_i)\n    for p in open_positions:\n        mark(p.get("symbol"), p.get("opened_ts"), n)\n    return mask\n\n\n\ndef drawdown_episodes(nav_history: list[tuple[str, float]],\n                      top_n: int = 5) -> list[dict[str, Any]]:\n    """Break a nav_history series into peak-to-trough drawdown episodes.\n\n    `stats()`\'s `max_dd` is a single number: the deepest point relative to\n    its own running peak. It doesn\'t say *when* that happened or whether it\n    was one bad stretch or several. This walks the same nav series and\n    returns each episode (peak date/nav, trough date/nav, depth, recovery\n    date if any) so the answer to "what period drives the drawdown" is a\n    date range, not a guess. Deepest episode\'s `dd_pct` reproduces\n    `stats()`\'s `max_dd` exactly (same running-peak definition).\n    """\n    if len(nav_history) < 3:\n        return []\n    episodes: list[dict[str, Any]] = []\n    peak_ts, peak_nav, peak_i = nav_history[0][0], nav_history[0][1], 0\n    trough_ts, trough_nav, trough_i = peak_ts, peak_nav, 0\n    in_drawdown = False\n\n    def close_episode(recovery_ts):\n        dd = trough_nav / peak_nav - 1 if peak_nav > 0 else 0.0\n        episodes.append({\n            "peak_ts": peak_ts, "peak_nav": float(peak_nav),\n            "trough_ts": trough_ts, "trough_nav": float(trough_nav),\n            "dd_pct": float(dd),\n            "peak_to_trough_bars": trough_i - peak_i,\n            "recovery_ts": recovery_ts,\n        })\n\n    for i, (ts, nav) in enumerate(nav_history[1:], start=1):\n        if nav >= peak_nav:\n            if in_drawdown:\n                close_episode(recovery_ts=ts)\n                in_drawdown = False\n            peak_ts, peak_nav, peak_i = ts, nav, i\n            trough_ts, trough_nav, trough_i = ts, nav, i\n        else:\n            in_drawdown = True\n            if nav < trough_nav:\n                trough_ts, trough_nav, trough_i = ts, nav, i\n    if in_drawdown:\n        close_episode(recovery_ts=None)\n    episodes.sort(key=lambda e: e["dd_pct"])\n    return episodes[:top_n]\n\n\ndef trade_anatomy(result: dict[str, Any], top_n: int = 5) -> dict[str, Any]:\n    """The full post-mortem on every closed trade.\n\n    A 60% win rate sitting next to a large negative stop-loss total is not a\n    contradiction, it is a shape: many small wins funding a few structural\n    losers. Aggregate stats hide that; this does not. Nothing here feeds\n    fitness — it exists so a human can see the internal economy before\n    deciding that another evolution generation is the useful next move.\n    """\n    trades = result.get("closed_trades", [])\n    if not trades:\n        return {"error": "no closed trades"}\n\n    # entry timestamp -> market regime, so P&L can be cut by conditions\n    regime_at = {d.get("ts"): d.get("regime") for d in result.get("decision_log", [])}\n\n    pnls = [float(t.get("pnl", 0.0)) for t in trades]\n    wins = [p for p in pnls if p > 0]\n    losses = [p for p in pnls if p <= 0]\n    gross_win, gross_loss = sum(wins), -sum(losses)\n    ranked = sorted(trades, key=lambda t: float(t.get("pnl", 0.0)))\n\n    def bucket(t):\n        b = int(t.get("bars_held", 0) or 0)\n        if b <= 1:\n            return "1 bar"\n        if b <= 5:\n            return "2-5 bars"\n        if b <= 20:\n            return "6-20 bars"\n        return "21+ bars"\n\n    def group(keyfn):\n        out: dict[str, dict] = {}\n        for t in trades:\n            for k in keyfn(t):\n                g = out.setdefault(str(k), {"n": 0, "pnl": 0.0, "wins": 0})\n                g["n"] += 1\n                g["pnl"] += float(t.get("pnl", 0.0))\n                if float(t.get("pnl", 0.0)) > 0:\n                    g["wins"] += 1\n        for g in out.values():\n            g["mean"] = g["pnl"] / max(g["n"], 1)\n            g["win_rate"] = g["wins"] / max(g["n"], 1)\n        return dict(sorted(out.items(), key=lambda kv: kv[1]["pnl"]))\n\n    def brief(t):\n        return {"symbol": t.get("symbol"), "pnl": round(float(t.get("pnl", 0.0)), 2),\n                "pnl_pct": round(float(t.get("pnl_pct", 0.0)), 4),\n                "bars_held": t.get("bars_held"),\n                "exit_reason": str(t.get("exit_reason", ""))[:60],\n                "entry_ts": str(t.get("entry_ts", ""))[:10]}\n\n    top_losses = [brief(t) for t in ranked[:top_n]]\n    return {\n        "n_trades": len(trades),\n        "expectancy": sum(pnls) / len(pnls),\n        "total_pnl": sum(pnls),\n        "win_rate": len(wins) / len(trades),\n        "median_win": float(np.median(wins)) if wins else 0.0,\n        "median_loss": float(np.median(losses)) if losses else 0.0,\n        "mean_win": float(np.mean(wins)) if wins else 0.0,\n        "mean_loss": float(np.mean(losses)) if losses else 0.0,\n        "profit_factor": (gross_win / gross_loss) if gross_loss > 1e-9 else float("inf"),\n        "largest_losses": top_losses,\n        "largest_wins": [brief(t) for t in ranked[::-1][:top_n]],\n        # If a handful of trades explain most of the damage, the real risk is\n        # tail-shaped and no amount of win-rate tuning addresses it.\n        "top_loss_share_of_gross_loss": (\n            sum(-x["pnl"] for x in top_losses) / gross_loss if gross_loss > 1e-9 else 0.0),\n        "by_entry_agent": group(lambda t: (t.get("entry_agents") or ["unattributed"])),\n        "by_exit_reason": group(lambda t: [str(t.get("exit_reason", "")).split(":")[0].strip()[:30]\n                                           or "unknown"]),\n        "by_symbol": group(lambda t: [t.get("symbol", "?")]),\n        "by_holding_period": group(lambda t: [bucket(t)]),\n        "by_regime": group(lambda t: [regime_at.get(t.get("entry_ts")) or "unrecorded"]),\n    }\n\n\ndef consult_correlation(result: dict[str, Any]) -> dict[str, Any]:\n    """Are the three consults actually three opinions?\n\n    The design claims momentum, mean reversion and confirmed trend are\n    different theories, and that their agreement therefore carries\n    information. That is a hypothesis about the *outputs*, and it has never\n    been measured. If two consults are 0.85 correlated, their agreement is one\n    opinion counted twice and the Risk Judge is reading its own echo.\n\n    Caveat, stated in the output because it changes the reading: the decision\n    log only records bars where something happened (a fill, a forced exit or a\n    veto), so these correlations describe agreement on active bars, not on all\n    bars.\n    """\n    log = result.get("decision_log", [])\n    if not log:\n        return {"error": "no decision log — run the backtest with log_detail=True"}\n\n    agents, signals = set(), {}\n    for d in log:\n        ts, regime = d.get("ts"), d.get("regime")\n        for agent, intents in (d.get("proposals") or {}).items():\n            agents.add(agent)\n            for i in intents:\n                side = i.get("side")\n                if side == "hold":\n                    continue\n                v = float(i.get("conviction", 0.0)) * (1.0 if side == "buy" else -1.0)\n                signals.setdefault(agent, {})[(ts, i.get("symbol"))] = (v, regime)\n    agents = sorted(agents)\n    if len(agents) < 2:\n        return {"error": "fewer than two consults recorded"}\n\n    keys = sorted({k for a in agents for k in signals.get(a, {})})\n\n    def vec(a, subset):\n        return np.array([signals.get(a, {}).get(k, (0.0, None))[0] for k in subset])\n\n    def corr(x, y):\n        if len(x) < 3 or float(np.std(x)) < 1e-9 or float(np.std(y)) < 1e-9:\n            return None\n        return float(np.corrcoef(x, y)[0, 1])\n\n    pairs: dict[str, Any] = {}\n    for i, a in enumerate(agents):\n        for b in agents[i + 1:]:\n            ka, kb = set(signals.get(a, {})), set(signals.get(b, {}))\n            union, inter = ka | kb, ka & kb\n            same_side = sum(1 for k in inter\n                            if (signals[a][k][0] > 0) == (signals[b][k][0] > 0))\n            pairs[f"{a} vs {b}"] = {\n                "signal_correlation": corr(vec(a, keys), vec(b, keys)),\n                "proposal_overlap_jaccard": len(inter) / len(union) if union else 0.0,\n                "same_side_when_both_act": (same_side / len(inter)) if inter else None,\n                "n_shared_proposals": len(inter),\n            }\n\n    by_regime: dict[str, Any] = {}\n    for r in sorted({v[1] for a in agents for v in signals.get(a, {}).values() if v[1]}):\n        sub = [k for k in keys\n               if any(signals.get(a, {}).get(k, (0.0, None))[1] == r for a in agents)]\n        if len(sub) < 10:\n            continue\n        by_regime[r] = {f"{a} vs {b}": corr(vec(a, sub), vec(b, sub))\n                        for i, a in enumerate(agents) for b in agents[i + 1:]}\n\n    trades = result.get("closed_trades", [])\n    multi = sum(1 for t in trades if len(t.get("entry_agents") or ()) > 1)\n    return {\n        "note": ("correlations cover bars the decision log recorded (fills, forced "\n                 "exits, vetoes) — not every bar"),\n        "n_active_bars": len(log),\n        "n_proposal_points": len(keys),\n        "pairs": pairs,\n        "by_regime": by_regime,\n        "trades_with_multiple_entry_agents": (multi / len(trades)) if trades else 0.0,\n    }\n\n\ndef edge_vs_benchmark(stats: dict[str, Any], bench: dict[str, Any],\n                      bars_per_year: float = 365.25) -> dict[str, Any]:\n    """What the council added over doing nothing at all.\n\n    Fitness is Sortino-shaped, and Sortino is perfectly capable of looking\n    healthy while the strategy quietly trails an equal-weight basket of the\n    same coins. That is the failure this exists to make unhideable: a rising\n    market lifts the council too, and "we made money" is not the claim — "we\n    made more than sitting still" is.\n\n    Reported, never optimised. Folding excess return into fitness would only\n    move the overfitting target; the point is that no promotion can be read\n    without also seeing what the lazy alternative did over the same bars.\n    """\n    if not bench or stats.get("error"):\n        return {}\n    yrs = max(float(stats.get("bars", 0)) / max(bars_per_year, 1e-9), 1e-6)\n\n    def annualise(total_return: float) -> float:\n        base = 1.0 + float(total_return)\n        if base <= 0.0:            # a wipeout has no meaningful CAGR\n            return -1.0\n        return base ** (1.0 / yrs) - 1.0\n\n    s_ret = float(stats.get("total_return", 0.0))\n    b_ret = float(bench.get("total_return", 0.0))\n    s_dd, b_dd = abs(float(stats.get("max_dd", 0.0))), abs(float(bench.get("max_dd", 0.0)))\n    return {\n        "excess_return": s_ret - b_ret,\n        "excess_return_annual": annualise(s_ret) - annualise(b_ret),\n        "excess_sharpe": float(stats.get("sharpe", 0.0)) - float(bench.get("sharpe", 0.0)),\n        "drawdown_delta": s_dd - b_dd,      # negative means shallower than the benchmark\n        "trades_per_year": float(stats.get("trades", 0)) / yrs,\n        "beat_benchmark": bool(s_ret > b_ret),\n    }\n\n\ndef run_backtest(genome: Genome, data: dict, start_frac: float = 0.0,\n                 end_frac: float = 1.0, log_detail: bool = True,\n                 warmup: int = 60) -> dict[str, Any]:\n    """Replay a slice of history through the full council."""\n    replay = Replay({s: df for s, df in data.items() if s in genome.universe})\n    n = len(replay)\n    if n < warmup + 120:\n        return {"error": f"not enough bars ({n})"}\n\n    start = max(warmup, int(n * start_frac))\n    end = min(n - 1, int(n * end_frac))\n    if end - start < 120:\n        return {"error": f"slice too short ({end - start} bars)"}\n\n    bcfg = genome.data.get("broker", {})\n    broker = PaperBroker(cash=float(bcfg.get("start_cash", 10_000.0)),\n                         fee_bps=float(bcfg.get("fee_bps", 10.0)),\n                         slippage_bps=float(bcfg.get("slippage_bps", 5.0)))\n    council = Council(genome, broker)\n\n    for i, window in replay.walk(start, end):\n        prices = {s: replay.close_at(s, i) for s in replay.data}\n        prices = {s: p for s, p in prices.items() if p is not None}\n        fills = {s: replay.next_open(s, i) for s in replay.data}\n        fills = {s: p for s, p in fills.items() if p is not None}\n        council.tick(window, prices, fills, log_detail=log_detail)\n\n    # final mark\n    last_prices = {s: replay.close_at(s, end) for s in replay.data}\n    last_prices = {s: p for s, p in last_prices.items() if p is not None}\n    broker.mark(str(replay.index[end]), last_prices, dd_halt=CIRCUIT_BREAKER_DD,\n                cooldown=CIRCUIT_BREAKER_COOLDOWN)\n\n    bpy = market.BARS_PER_YEAR.get(genome.bar_interval, 365.25)\n    stats = broker.stats(bars_per_year=bpy)\n    bench = benchmark_buy_hold(replay, genome.universe, start, end,\n                               float(bcfg.get("start_cash", 10_000.0)),\n                               bars_per_year=bpy)\n    return {\n        "genome_version": genome.version,\n        "window": {"start": str(replay.index[start]), "end": str(replay.index[end]),\n                   "bars": end - start},\n        "stats": stats,\n        "fitness": fitness(stats),\n        "benchmark": bench,\n        "edge": edge_vs_benchmark(stats, bench, bars_per_year=bpy),\n        "nav_history": broker.nav_history,\n        "closed_trades": [asdict(t) for t in broker.closed],\n        "open_positions": [{"symbol": p.symbol, "opened_ts": p.opened_ts}\n                           for p in broker.positions.values() if p.is_open],\n        "decision_log": council.decision_log,\n        "superior_overrides": council.superior.override_count,\n        "override_samples": council.superior.overrides[:20],\n        "exec": {"filled": council.trader.executed, "rejected": council.trader.rejected},\n    }\n\n\ndef block_bootstrap_resample(rets: np.ndarray, length: int, block_size: int,\n                             rng: np.random.Generator) -> np.ndarray:\n    """Circular moving-block bootstrap of a return series.\n\n    Resamples `rets` into a new series of `length` bars, built from\n    `block_size`-bar chunks starting at randomly chosen (circularly wrapped)\n    positions in the original series. A per-bar i.i.d. resample would destroy\n    the short-range autocorrelation real return series have (volatility\n    clustering, multi-bar trends); sampling whole blocks instead preserves\n    that local structure while still letting the *sequence of blocks* vary.\n    Standard technique for bootstrapping a Sharpe/Sortino-style ratio\'s\n    sampling distribution from one observed path.\n\n    `block_size` is clamped to `[1, len(rets)]` so a too-large request\n    degenerates to "one block, still random start" rather than raising.\n    """\n    n = len(rets)\n    if n == 0:\n        return rets.copy()\n    block_size = max(1, min(block_size, n))\n    n_blocks = math.ceil(length / block_size)\n    starts = rng.integers(0, n, size=n_blocks)\n    chunks = [rets[(s + np.arange(block_size)) % n] for s in starts]\n    return np.concatenate(chunks)[:length]\n\n\ndef stats_from_returns(rets: np.ndarray, trades: int, turnover_annual: float,\n                       bars_per_year: float) -> dict[str, Any]:\n    """The return-derived subset of `core.portfolio.PaperBroker.stats()`,\n    computed from a bare return series instead of a live broker.\n\n    Deliberately duplicates that method\'s formulas (total_return, cagr, vol,\n    sharpe, sortino, max_dd) rather than importing them, because\n    `PaperBroker.stats()` reads `self.closed`/`self.fills` for the\n    trade-derived fields (trades, win_rate, turnover, ...) that a bootstrap\n    resample of *returns* has no way to regenerate -- reordering bars doesn\'t\n    tell you which trades would have fired in that order. `trades` and\n    `turnover_annual` are passed through unchanged from the real backtest\n    instead: this function only asks "how much does the *return path*, on\n    its own, move the return-derived half of fitness". Verified to reproduce\n    `PaperBroker.stats()` exactly when fed that broker\'s own realized returns\n    unshuffled (`tests/test_bootstrap_holdout_noise.py`).\n    """\n    nav = np.concatenate([[1.0], np.cumprod(1.0 + rets)])\n    if len(nav) < 3:\n        return {"error": "insufficient history", "trades": trades}\n    total = nav[-1] / nav[0] - 1\n    yrs = max(len(nav) / bars_per_year, 1e-6)\n    cagr = (nav[-1] / nav[0]) ** (1 / yrs) - 1 if nav[0] > 0 else 0.0\n    vol = float(np.std(rets, ddof=1)) * math.sqrt(bars_per_year) if len(rets) > 2 else 0.0\n    downside = rets[rets < 0]\n    dd_dev = float(np.std(downside, ddof=1)) * math.sqrt(bars_per_year) if len(downside) > 2 else 0.0\n    sharpe = float(np.mean(rets)) * bars_per_year / vol if vol > 1e-9 else 0.0\n    sortino = float(np.mean(rets)) * bars_per_year / dd_dev if dd_dev > 1e-9 else 0.0\n    peaks = np.maximum.accumulate(nav)\n    max_dd = float(np.min(nav / np.maximum(peaks, 1e-9) - 1))\n    return {\n        "total_return": float(total), "cagr": float(cagr), "vol": vol,\n        "sharpe": sharpe, "sortino": sortino, "max_dd": max_dd,\n        "bars": len(nav), "trades": trades, "turnover_annual": turnover_annual,\n    }\n\n\ndef bootstrap_fitness_distribution(nav_history: list[tuple[str, float]], trades: int,\n                                   turnover_annual: float, bars_per_year: float,\n                                   n_boot: int = 1000, block_size: int = 10,\n                                   seed: int = 0) -> dict[str, Any]:\n    """How noisy is a single sealed-holdout fitness score, just from the\n    order returns happened to arrive in?\n\n    `constitution.holdout_accepts()`\'s own docstring says the margin it\n    applies "is a floor, not a calibration... Measure the sigma before\n    trusting the number" -- this is that measurement. Block-bootstraps the\n    observed holdout-window return path `n_boot` times (see\n    `block_bootstrap_resample`), recomputes the return-derived stats and\n    `constitution.fitness()` for each resample via `stats_from_returns`\n    (holding `trades`/`turnover_annual` fixed at the real backtest\'s own\n    values -- see that function\'s docstring for why), and reports the\n    resulting distribution. `boot_fitness_std` is the empirical sigma to\n    compare against `constitution.MULTIPLE_TESTING_SIGMA` (0.08): if the\n    empirical sigma is meaningfully larger, the sealed-holdout margin is\n    tuned too tight for how noisy a short holdout window actually is, and a\n    "beats the champion" verdict from `holdout_accepts()` is less trustworthy\n    than the margin implies.\n\n    Read-only and genome-independent in itself -- takes an already-computed\n    `nav_history` from one real `run_backtest()` call, never runs a genome or\n    touches `live_state.json`. `seed` is fixed by default for a reproducible\n    report; pass a different one to sanity-check the result isn\'t a seed\n    artifact.\n    """\n    nav = np.array([v for _, v in nav_history], dtype=float)\n    if len(nav) < 3:\n        return {"error": "insufficient nav history"}\n    rets = np.diff(nav) / np.maximum(nav[:-1], 1e-9)\n    real_stats = stats_from_returns(rets, trades, turnover_annual, bars_per_year)\n    real_fitness = fitness(real_stats)\n\n    rng = np.random.default_rng(seed)\n    bs = max(1, min(block_size, len(rets)))\n    fits, sortinos, maxdds, tot_rets = [], [], [], []\n    for _ in range(n_boot):\n        sample = block_bootstrap_resample(rets, len(rets), bs, rng)\n        st = stats_from_returns(sample, trades, turnover_annual, bars_per_year)\n        fits.append(fitness(st))\n        sortinos.append(st.get("sortino", 0.0))\n        maxdds.append(st.get("max_dd", 0.0))\n        tot_rets.append(st.get("total_return", 0.0))\n\n    fits_arr = np.array(fits)\n    finite = fits_arr[np.isfinite(fits_arr)]\n    return {\n        "n_boot": n_boot, "block_size": bs, "bars": len(rets),\n        "real_fitness": real_fitness,\n        "real_sortino": real_stats.get("sortino", 0.0),\n        "real_max_dd": real_stats.get("max_dd", 0.0),\n        "real_total_return": real_stats.get("total_return", 0.0),\n        "boot_fitness_mean": float(np.mean(finite)) if len(finite) else float("-inf"),\n        "boot_fitness_std": float(np.std(finite, ddof=1)) if len(finite) > 2 else 0.0,\n        "boot_fitness_p05": float(np.percentile(finite, 5)) if len(finite) else float("-inf"),\n        "boot_fitness_p95": float(np.percentile(finite, 95)) if len(finite) else float("-inf"),\n        "frac_hard_fail": float(np.mean(~np.isfinite(fits_arr))),\n        "sortino_std": float(np.std(sortinos, ddof=1)) if len(sortinos) > 2 else 0.0,\n        "total_return_std": float(np.std(tot_rets, ddof=1)) if len(tot_rets) > 2 else 0.0,\n        "max_dd_p05": float(np.percentile(maxdds, 5)) if maxdds else 0.0,\n        "max_dd_p95": float(np.percentile(maxdds, 95)) if maxdds else 0.0,\n    }\n'
_SRC['loop.evolve'] = '"""THE EVOLUTION LOOP.\n\n    Researcher proposes  ->  Evaluator walk-forwards  ->  Superior Judge commits\n\nThe Evaluator is the honest broker. It never gets an opinion; it produces\nnumbers on data the proposal was not derived from. The Superior Judge applies\nthe constitution\'s acceptance rules and is the only thing that can write a new\nchampion genome.\n\nThree anti-self-delusion measures live here:\n\n  * **Walk-forward folds.** A challenger is scored on several disjoint future\n    slices, not one. Aggregate fitness is penalised for variance across folds:\n    a strategy that works in one fold and dies in the next isn\'t a strategy,\n    it\'s a coincidence that hasn\'t been caught yet.\n\n  * **Sealed holdout.** The newest slice of history is untouched during search\n    and used only for the final confirmation. Anything that only looks good\n    until it meets the holdout gets rejected there.\n\n  * **Multiple-testing penalty.** Testing 40 mutations and crowning the best\n    one is how you manufacture a champion out of noise. The required margin\n    scales with how many candidates were tried.\n"""\nfrom __future__ import annotations\n\nimport json\nimport math\nimport os\nimport re\nimport time\nfrom dataclasses import asdict\nfrom typing import Any\n\nimport numpy as np\n\nfrom agents.researcher import Researcher, diagnose\nfrom constitution import (FOLD_CONSISTENCY_WEIGHT, HOLDOUT_FRAC, N_FOLDS,\n                          RANK_FLOOR, accepts, fitness, holdout_accepts,\n                          ranking_fitness)\nfrom core.genome import Genome\nfrom core.types import Mutation\nfrom loop.engine import run_backtest\n\nROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\nLINEAGE_PATH = os.path.join(ROOT, "state", "lineage.jsonl")\n\n\ndef rolling_folds(search_end: float, base_n_folds: int = N_FOLDS,\n                   overlap: float = 0.5) -> list[tuple[float, float]]:\n    """Overlapping, fixed-width windows spanning the searchable region.\n\n    `fold-scheme` (raising n_folds on the fixed disjoint split) shrinks every\n    window as the count grows, and at n_folds=8 one window came within 25 bars\n    of run_backtest\'s hard minimum and another failed a hard gate outright --\n    see AGENTS.md\'s fold-scheme entries. This is the other way to get more\n    reads of the same span: keep window width fixed at whatever\n    Evaluator.folds() already uses for `base_n_folds`, and slide that\n    fixed-size window across the region instead of subdividing it, so no\n    window ever shrinks below its base_n_folds size. The windows overlap and\n    are therefore not independent draws -- this is a smoothing diagnostic on\n    how much a single dominant window (e.g. the permanent fold-2 melt-up) can\n    still swing aggregate_fitness, not a replacement evaluation scheme.\n\n    overlap=0.0 reproduces Evaluator.folds()\'s own disjoint edges at\n    n_folds=base_n_folds (same count, same windows); overlap approaching 1.0\n    produces many nearly-identical windows one bar apart.\n    """\n    if not (0.0 <= overlap < 1.0):\n        raise ValueError("overlap must be in [0, 1)")\n    if base_n_folds < 1:\n        raise ValueError("base_n_folds must be >= 1")\n    width = search_end / base_n_folds\n    stride = width * (1.0 - overlap)\n    if stride <= 0.0:\n        raise ValueError("stride must be positive")\n    windows = []\n    start = 0.0\n    while start + width <= search_end + 1e-9:\n        windows.append((start, min(start + width, search_end)))\n        start += stride\n    return windows\n\n\ndef fitness_decomposition(fold_fits: list[float]) -> dict[str, float]:\n    """Split aggregate_fitness into its mean and consistency-penalty terms.\n\n    Evaluator.evaluate scores a genome as\n    ``mean(fold_fits) - FOLD_CONSISTENCY_WEIGHT * std(fold_fits)``. fold-scheme\n    and rolling-folds both showed that changing the fold windowing swings that\n    single aggregate number, but the aggregate alone can\'t say *why*: a swing\n    could come from the mean term (the outlier fold pulling the average) or\n    from the penalty term (the cross-fold spread the FOLD_CONSISTENCY_WEIGHT\n    std penalty reads). The rolling-folds run hypothesised the penalty term is\n    the culprit -- adding more overlapping windows adds variance to std at\n    least as fast as it dilutes the outlier\'s share of the mean. This returns\n    both terms separately so that hypothesis is measurable, not asserted.\n\n    ``mean_term - penalty_term`` reconstructs aggregate_fitness exactly (same\n    np.mean/np.std this uses), so the decomposition is an identity, not an\n    approximation. Empty input returns -inf aggregate with zero terms, matching\n    Evaluator.evaluate\'s own empty-folds branch.\n    """\n    if not fold_fits:\n        return {"mean_term": 0.0, "std": 0.0, "penalty_term": 0.0,\n                "aggregate_fitness": float("-inf"), "n_folds": 0}\n    arr = np.asarray(fold_fits, dtype=float)\n    mean_term = float(np.mean(arr))\n    std = float(np.std(arr))\n    penalty_term = float(FOLD_CONSISTENCY_WEIGHT * std)\n    return {"mean_term": mean_term, "std": std, "penalty_term": penalty_term,\n            "aggregate_fitness": mean_term - penalty_term,\n            "n_folds": int(arr.size)}\n\n\ndef capped_fitness_decomposition(fold_fits: list[float], cap_z: float = 1.0) -> dict[str, Any]:\n    """Winsorize the mean term against a single dominant fold, leaving the\n    consistency-penalty term untouched, and report both the plain and capped\n    aggregate side by side.\n\n    fitness-decomp (2026-08-20) settled that aggregate_fitness\'s swing across\n    fold schemes rides the *mean* term (one outlier fold), not the\n    FOLD_CONSISTENCY_WEIGHT * std penalty term, in all three real champions.\n    regime-folds\' n_subwindows/n_folds sweep (2026-08-21) then showed that\n    *isolating* the outlier into its own fold is double-edged -- it helps at\n    low fold counts but isolating a weak fold the same way costs more than it\n    gains at higher counts. That leaves the fix AGENTS.md\'s Current state\n    flagged as the sharper remaining option: cap the outlier\'s pull on the\n    mean term directly, rather than reshuffling which folds exist at all.\n\n    This winsorizes each fold fitness to a ceiling of ``mean(fold_fits) +\n    cap_z * std(fold_fits)`` (a standard symmetric-from-above outlier cap --\n    values below the ceiling are untouched, nothing is capped from below,\n    since the concern here is one fold pulling the mean *up*, not down) before\n    taking the mean. The ceiling and which folds get capped are computed from\n    the *original* fold_fits, so this is deterministic and not iterative. The\n    consistency-penalty term is deliberately computed from the ORIGINAL\n    (uncapped) fold_fits, not the capped ones: that penalty already exists to\n    punish cross-fold spread, so capping it too would double-count the same\n    concern the mean-capping is meant to isolate -- this diagnostic asks\n    whether capping the mean term ALONE stabilizes the aggregate, not whether\n    capping everything does.\n\n    Degenerate cases: a single fold or zero-spread fold set has std=0, so the\n    ceiling equals the mean and nothing gets capped -- ``capped_mean_term ==\n    mean_term`` exactly, matching fitness_decomposition\'s own single-fold/\n    zero-spread behavior. Empty input returns the same -inf/zero shape\n    fitness_decomposition uses for its empty branch.\n    """\n    if not fold_fits:\n        return {"mean_term": 0.0, "capped_mean_term": 0.0, "std": 0.0,\n                "penalty_term": 0.0, "aggregate_fitness": float("-inf"),\n                "capped_aggregate_fitness": float("-inf"),\n                "n_folds": 0, "n_capped": 0, "cap_z": float(cap_z)}\n    arr = np.asarray(fold_fits, dtype=float)\n    mean_term = float(np.mean(arr))\n    std = float(np.std(arr))\n    penalty_term = float(FOLD_CONSISTENCY_WEIGHT * std)\n    ceiling = mean_term + cap_z * std\n    capped = np.minimum(arr, ceiling)\n    n_capped = int(np.sum(arr > ceiling + 1e-12))\n    capped_mean_term = float(np.mean(capped))\n    return {"mean_term": mean_term, "capped_mean_term": capped_mean_term,\n            "std": std, "penalty_term": penalty_term,\n            "aggregate_fitness": mean_term - penalty_term,\n            "capped_aggregate_fitness": capped_mean_term - penalty_term,\n            "n_folds": int(arr.size), "n_capped": n_capped,\n            "cap_z": float(cap_z)}\n\n\ndef regime_concentration(window_returns: list[float]) -> dict[str, Any]:\n    """Quantify how concentrated the searchable region\'s compounded growth is\n    across contiguous sub-windows -- genome-independent.\n\n    fitness-decomp (2026-08-20) settled that aggregate_fitness\'s instability\n    across fold schemes is driven by the *mean* of the fold fitnesses, not the\n    FOLD_CONSISTENCY_WEIGHT penalty term, in all three real champions. The mean\n    moves because one window -- fold 2 in the fixed 3-fold split, a permanent\n    +200% melt-up per the `regime` diagnostic -- dominates the average. Every\n    run since lands on the same untried fix: a regime-stratified fold scheme\n    that spreads that melt-up across folds so no single fold is a permanent\n    outlier. But that fix needs engine work `run_backtest` can\'t do yet\n    (folds would become non-contiguous unions of bars), so before committing\n    to it, one number has gone unmeasured: is the melt-up ISOLATED to a tight\n    calendar stretch (stratification would help) or DIFFUSE across the region\n    (it wouldn\'t, and the effort should go to MULTIPLE_TESTING_SIGMA instead)?\n    This measures exactly that.\n\n    Each contiguous window\'s contribution to the region\'s total compounded\n    growth is its log-return ``log(1 + r)``; those sum across the region to its\n    total log-growth (compounding is additive in logs). Concentration is\n    reported over the ABSOLUTE log-returns, so a deep crash counts as a large\n    contribution rather than cancelling a melt-up out -- both are exactly the\n    kind of dominant single window that swings the fold mean. Shares are\n    ``p_i = |L_i| / sum_j |L_j|``; ``hhi = sum p_i^2`` runs from ``1/n``\n    (perfectly even) to ``1`` (all in one window); ``top_share`` is the single\n    largest with the window index that carries it; ``concentration_ratio =\n    top_share * n`` is how many times its even share the richest window holds\n    (1.0 = even, >1 = concentrated). Empty input returns zeros.\n    """\n    n = len(window_returns)\n    if n == 0:\n        return {"n_windows": 0, "shares": [], "hhi": 0.0, "top_index": -1,\n                "top_share": 0.0, "top_return": 0.0, "even_share": 0.0,\n                "concentration_ratio": 0.0, "total_log_growth": 0.0,\n                "total_return": 0.0}\n    logs = [math.log(max(1.0 + r, 1e-12)) for r in window_returns]\n    abs_logs = [abs(x) for x in logs]\n    total_abs = sum(abs_logs)\n    if total_abs <= 0.0:\n        shares = [1.0 / n] * n\n    else:\n        shares = [x / total_abs for x in abs_logs]\n    hhi = float(sum(s * s for s in shares))\n    top_index = max(range(n), key=lambda i: shares[i])\n    top_share = float(shares[top_index])\n    even_share = 1.0 / n\n    total_log = float(sum(logs))\n    return {"n_windows": n, "shares": shares, "hhi": hhi,\n            "top_index": int(top_index), "top_share": top_share,\n            "top_return": float(window_returns[top_index]),\n            "even_share": even_share,\n            "concentration_ratio": top_share / even_share,\n            "total_log_growth": total_log,\n            "total_return": float(math.exp(total_log) - 1.0)}\n\n\ndef regime_stratified_groups(window_returns: list[float], n_folds: int) -> list[list[int]]:\n    """Assign sub-window indices to `n_folds` groups by greedy longest-\n    processing-time (LPT) balancing on each window\'s |log(1+r)| weight -- the\n    same weight `regime_concentration` shares its `concentration_ratio` from.\n\n    regime-scan (2026-08-20) measured the searchable region\'s compounded\n    growth as concentrated ~2.5x its even share in one or two sub-windows, and\n    fitness-decomp (2026-08-20) showed that concentration reaching\n    aggregate_fitness\'s mean term (not the consistency penalty) is what makes\n    it swing across fold schemes -- the fixed 3-fold calendar split just\n    happens to trap the whole melt-up in one fold. This groups finer\n    sub-windows into folds so no fold hoards a disproportionate share of the\n    region\'s growth instead. AGENTS.md\'s item 2 assumed this needed\n    `run_backtest` to replay a non-contiguous union of bars; it doesn\'t --\n    `Evaluator.evaluate_grouped` scores a group by backtesting each of its\n    sub-windows independently (state resets at each boundary, same as at\n    every existing fold boundary) and merging the results, so this function\n    only needs to produce the *grouping*, which is genome-independent.\n\n    LPT: sort sub-windows by descending weight (ties broken by ascending\n    index, for determinism), then repeatedly assign the next-heaviest\n    sub-window to whichever fold currently holds the least total weight\n    (ties broken by lowest fold index). This is the standard heuristic for\n    balancing a fixed number of bins by load and is optimal-ish for makespan,\n    not just plausible.\n\n    `n_folds` must be >= 1. More folds than sub-windows leaves the extra\n    folds empty (their fitness floors at RANK_FLOOR at evaluation time, same\n    as `evaluate()`\'s own empty-folds branch). Empty `window_returns` returns\n    `n_folds` empty groups.\n    """\n    if n_folds < 1:\n        raise ValueError("n_folds must be >= 1")\n    groups: list[list[int]] = [[] for _ in range(n_folds)]\n    n = len(window_returns)\n    if n == 0:\n        return groups\n    weights = [abs(math.log(max(1.0 + r, 1e-12))) for r in window_returns]\n    order = sorted(range(n), key=lambda i: (-weights[i], i))\n    totals = [0.0] * n_folds\n    for i in order:\n        j = min(range(n_folds), key=lambda k: (totals[k], k))\n        groups[j].append(i)\n        totals[j] += weights[i]\n    return groups\n\n\nclass Evaluator:\n    """Minor judge for the evolution track. Reports numbers, never opinions."""\n\n    name = "evaluator"\n\n    def __init__(self, data: dict, n_folds: int = N_FOLDS,\n                 holdout_frac: float = HOLDOUT_FRAC):\n        self.data = data\n        self.n_folds = n_folds\n        self.search_end = 1.0 - holdout_frac      # search may never look past here\n        self.holdout = (self.search_end, 1.0)\n\n    def folds(self) -> list[tuple[float, float]]:\n        """Disjoint, chronological slices of the searchable region."""\n        edges = np.linspace(0.0, self.search_end, self.n_folds + 1)\n        return [(float(edges[i]), float(edges[i + 1])) for i in range(self.n_folds)]\n\n    def evaluate(self, g: Genome, folds: list[tuple[float, float]] | None = None,\n                 log_detail: bool = False) -> dict[str, Any]:\n        folds = folds or self.folds()\n        per_fold, fits = [], []\n        for a, b in folds:\n            r = run_backtest(g, self.data, a, b, log_detail=log_detail)\n            if "error" in r:\n                per_fold.append({"window": [a, b], "error": r["error"]})\n                fits.append(RANK_FLOOR)\n                continue\n            per_fold.append({"window": [a, b], "stats": r["stats"],\n                             "fitness": r["fitness"],\n                             "rank_fitness": ranking_fitness(r["stats"]),\n                             "benchmark": r.get("benchmark", {}),\n                             "edge": r.get("edge", {})})\n            fits.append(ranking_fitness(r["stats"]))\n\n        if not fits:\n            agg = float("-inf")\n        else:\n            # mean minus cross-fold spread: consistency is part of the score,\n            # not a footnote. One great fold and one disaster is not an edge.\n            agg = float(np.mean(fits) - FOLD_CONSISTENCY_WEIGHT * np.std(fits))\n\n        # aggregate stats across folds, for the acceptance gates\n        merged = self._merge([f for f in per_fold if "stats" in f])\n        return {"folds": per_fold, "fold_fitness": fits,\n                "aggregate_fitness": agg, "stats": merged,\n                "edge": self._merge_edge([f for f in per_fold if f.get("edge")])}\n\n    def evaluate_grouped(self, g: Genome, sub_windows: list[tuple[float, float]],\n                          groups: list[list[int]],\n                          log_detail: bool = False) -> dict[str, Any]:\n        """Evaluate a genome under folds built from `regime_stratified_groups`\n        instead of one contiguous slice per fold. Backs the `regime-folds`\n        diagnostic -- the first real test of the regime-stratified fold idea\n        that doesn\'t need an engine or constitution change (see that\n        function\'s docstring for why).\n\n        Each sub-window in a group gets its own independent `run_backtest`\n        call -- no non-contiguous replay, genome state (positions, indicator\n        lookback windows) simply resets at every sub-window boundary within a\n        fold, exactly as it already does at every boundary between today\'s\n        three calendar folds. A group\'s sub-window results are combined with\n        the same trade-weighted `_merge` this class already uses to combine\n        folds for the acceptance gates, then scored with the same\n        `ranking_fitness` used per-fold in `evaluate()`. The final\n        `aggregate_fitness` uses the identical `mean - FOLD_CONSISTENCY_WEIGHT\n        * std` formula across folds, so its number is directly comparable to\n        `evaluate()`\'s own `aggregate_fitness` at the same fold count -- this\n        is an approximation of a genuinely non-contiguous single replay (which\n        would need `run_backtest` itself to change), not that replay, but it\n        needs nothing checksummed to measure whether balancing regime\n        concentration across folds stabilizes the aggregate.\n        """\n        per_fold, fits = [], []\n        for group in groups:\n            sub_results = []\n            for idx in group:\n                a, b = sub_windows[idx]\n                r = run_backtest(g, self.data, a, b, log_detail=log_detail)\n                if "error" not in r:\n                    sub_results.append(r)\n            windows = [sub_windows[i] for i in group]\n            if not sub_results:\n                per_fold.append({"sub_windows": windows,\n                                 "error": "no valid sub-windows"})\n                fits.append(RANK_FLOOR)\n                continue\n            merged = self._merge([{"stats": r["stats"]} for r in sub_results])\n            fit = ranking_fitness(merged)\n            per_fold.append({"sub_windows": windows, "stats": merged,\n                             "fitness": fit, "n_sub_windows": len(group),\n                             "n_sub_windows_ok": len(sub_results)})\n            fits.append(fit)\n\n        if not fits:\n            agg = float("-inf")\n        else:\n            agg = float(np.mean(fits) - FOLD_CONSISTENCY_WEIGHT * np.std(fits))\n        return {"folds": per_fold, "fold_fitness": fits, "aggregate_fitness": agg}\n\n    @staticmethod\n    def _merge_edge(folds: list[dict]) -> dict[str, Any]:\n        """Mean edge across folds, plus how many of them actually beat the\n        benchmark. Three folds averaging positive because one was spectacular\n        is a different claim from three folds that each cleared the bar."""\n        if not folds:\n            return {}\n        e = [f["edge"] for f in folds]\n        beat = sum(1 for x in e if x.get("beat_benchmark"))\n        return {\n            "excess_return": float(np.mean([x.get("excess_return", 0.0) for x in e])),\n            "excess_return_annual": float(np.mean(\n                [x.get("excess_return_annual", 0.0) for x in e])),\n            "excess_sharpe": float(np.mean([x.get("excess_sharpe", 0.0) for x in e])),\n            "drawdown_delta": float(np.mean([x.get("drawdown_delta", 0.0) for x in e])),\n            "trades_per_year": float(np.mean([x.get("trades_per_year", 0.0) for x in e])),\n            "folds_beating_benchmark": f"{beat}/{len(e)}",\n        }\n\n    @staticmethod\n    def _merge(folds: list[dict]) -> dict[str, Any]:\n        if not folds:\n            return {"error": "no folds"}\n        s = [f["stats"] for f in folds]\n        return {\n            "trades": sum(x.get("trades", 0) for x in s),\n            "bars": sum(x.get("bars", 0) for x in s),\n            "sortino": float(np.mean([x.get("sortino", 0) for x in s])),\n            "sharpe": float(np.mean([x.get("sharpe", 0) for x in s])),\n            "max_dd": float(np.min([x.get("max_dd", 0) for x in s])),\n            "turnover_annual": float(np.mean([x.get("turnover_annual", 0) for x in s])),\n            "win_rate": float(np.mean([x.get("win_rate", 0) for x in s])),\n            "total_return": float(np.mean([x.get("total_return", 0) for x in s])),\n            "halt_count": sum(x.get("halt_count", 0) for x in s),\n        }\n\n    def holdout_check(self, g: Genome) -> dict[str, Any]:\n        r = run_backtest(g, self.data, *self.holdout, log_detail=False)\n        if "error" in r:\n            return {"error": r["error"]}\n        return {"stats": r["stats"], "fitness": r["fitness"],\n                "benchmark": r.get("benchmark", {}), "edge": r.get("edge", {})}\n\n\nclass EvolutionRun:\n    def __init__(self, data: dict, seed: int | None = 7, verbose: bool = True,\n                 initial_tested: set | None = None, initial_stagnation: int = 0,\n                 initial_champion_version: int | None = None,\n                 initial_holdout_draws: int = 0):\n        self.data = data\n        self.evaluator = Evaluator(data)\n        self.researcher = Researcher(seed)\n        self.verbose = verbose\n        self.log: list[dict] = []\n        # Proposals already ruled out against the current champion, and how\n        # long that champion has stood. Both reset the moment it is beaten.\n        #\n        # Seeded from live_state.json\'s researcher_memory (keyed by champion\n        # version) when the caller has it -- otherwise every fresh `evolve` CLI\n        # invocation forgets what it already rejected against an unbeaten\n        # champion and re-spends backtests re-discovering the same near-miss\n        # candidates generation after generation, invocation after invocation.\n        self.tested: set = set(initial_tested or ())\n        self.tested_version: int | None = initial_champion_version\n        self.stagnation = int(initial_stagnation)\n        # Draws against the sealed holdout, counted for the life of the\n        # lineage. Deliberately NOT reset when the champion changes: the\n        # holdout is the same slice of history before and after a\n        # promotion, so a promotion does not restore its innocence.\n        self.holdout_draws = int(initial_holdout_draws)\n\n    def _say(self, msg: str) -> None:\n        if self.verbose:\n            print(msg, flush=True)\n\n    def generation(self, champion: Genome, n_blind: int = 14) -> tuple[Genome, dict]:\n        t0 = time.time()\n\n        # 1. what does the champion actually do, and where does it leak?\n        diag_run = run_backtest(champion, self.data, 0.0, self.evaluator.search_end,\n                                log_detail=True)\n        diag = diagnose(diag_run)\n        champ_eval = self.evaluator.evaluate(champion)\n        champ_fit = champ_eval["aggregate_fitness"]\n        self._say(f"  champion v{champion.version}: fitness {champ_fit:.3f}  "\n                  f"({diag[\'trades\']} trades, win {diag[\'win_rate\']:.0%}, "\n                  f"stops {diag[\'stop_share\']:.0%}, halts {diag[\'halt_count\']})")\n\n        if self.tested_version != champion.version:\n            self.tested = set()\n            self.tested_version = champion.version\n            self.stagnation = 0\n\n        # 2. propose — skipping anything already rejected against this champion\n        mutations = self.researcher.propose(\n            champion, diag, n_blind=n_blind, exclude=self.tested,\n            boldness=float(self.stagnation))\n        for m in mutations:\n            self.tested.add(self.researcher.key(m))\n        # Multiple testing is CUMULATIVE against a fixed champion: every\n        # candidate ever tried against it is another draw from the same urn.\n        # Counting only this generation\'s batch would understate the bias and\n        # let a long unbeaten search crown noise.\n        n_tested = len(self.tested)\n        self._say(f"  researcher: {len(mutations)} new proposals "\n                  f"({n_tested} tried against v{champion.version}, "\n                  f"boldness {self.stagnation})")\n        if not mutations:\n            self.stagnation += 1\n            self._say("  researcher exhausted its ideas this round")\n            self._record({"champion_version": champion.version,\n                          "champion_fitness": champ_fit, "n_candidates": 0,\n                          "note": "no new proposals"})\n            return champion, {"champion_version": champion.version, "n_candidates": 0}\n\n        # 3. evaluate every one on walk-forward folds\n        results = []\n        for m in mutations:\n            child = champion.child(list(m.patch.items()), note=m.hypothesis)\n            ev = self.evaluator.evaluate(child)\n            results.append((ev["aggregate_fitness"], m, child, ev))\n        results.sort(key=lambda x: (-np.inf if not np.isfinite(x[0]) else -x[0]))\n\n        # 4. the Superior Judge rules on the best candidate\n        gen_record = {\n            "champion_version": champion.version,\n            "champion_fitness": champ_fit,\n            "champion_stats": champ_eval["stats"],\n            "champion_edge": champ_eval.get("edge", {}),\n            "diagnosis": diag,\n            "n_candidates": len(mutations),\n            "n_tested_cumulative": n_tested,\n            "holdout_draws_before": self.holdout_draws,\n            "stagnation": self.stagnation,\n            "top": [{"fitness": (None if not np.isfinite(f) else round(f, 4)),\n                     "kind": m.kind, "target": m.target,\n                     "hypothesis": m.hypothesis, "patch": m.patch}\n                    for f, m, _, _ in results[:8]],\n            "seconds": 0.0,\n        }\n\n        for fit, m, child, ev in results[:3]:\n            if not np.isfinite(fit):\n                continue\n            ok, why = accepts(champ_eval["stats"], ev["stats"],\n                              n_candidates=n_tested,\n                              complexity_delta=max(0, m.complexity_delta),\n                              champion_score=champ_fit,\n                              challenger_score=fit)\n            if not ok:\n                gen_record.setdefault("rejections", []).append(\n                    {"target": m.target, "why": why, "fold_fitness": round(fit, 4)})\n                continue\n\n            # 5. sealed holdout — the last honest test\n            ho_champ = self.evaluator.holdout_check(champion)\n            ho_chal = self.evaluator.holdout_check(child)\n            # Every challenger that reaches this gate is one more draw\n            # against the same bars. Count it before judging it.\n            self.holdout_draws += 1\n            if ho_chal.get("error"):\n                ho_ok = False\n                ho_why = f"challenger produced no holdout result: {ho_chal[\'error\']}"\n            else:\n                ho_ok, ho_why = holdout_accepts(\n                    ho_champ.get("fitness", float("-inf")),\n                    ho_chal.get("fitness", float("-inf")),\n                    n_draws=self.holdout_draws)\n            gen_record["holdout"] = {"champion": ho_champ.get("fitness"),\n                                     "challenger": ho_chal.get("fitness"),\n                                     "draws": self.holdout_draws,\n                                     "passed": bool(ho_ok), "why": ho_why}\n            if not ho_ok:\n                gen_record.setdefault("rejections", []).append({\n                    "target": m.target, "why": ho_why,\n                    "fold_fitness": round(fit, 4)})\n                continue\n\n            child.promote()\n            gen_record["accepted"] = {\n                "new_version": child.version, "kind": m.kind, "target": m.target,\n                "edge": ev.get("edge", {}), "holdout_edge": ho_chal.get("edge", {}),\n                "hypothesis": m.hypothesis, "patch": m.patch,\n                "fitness": round(fit, 4), "was": round(champ_fit, 4), "why": why}\n            gen_record["seconds"] = round(time.time() - t0, 1)\n            self._say(f"  ACCEPTED v{child.version}: {m.hypothesis}")\n            self._say(f"    fitness {champ_fit:.3f} -> {fit:.3f} | {why}")\n            self._record(gen_record)\n            return child, gen_record\n\n        gen_record["seconds"] = round(time.time() - t0, 1)\n        self.stagnation += 1\n        self._say(f"  no proposal cleared the bar (best {results[0][0]:.3f} "\n                  f"vs champion {champ_fit:.3f}) — champion holds")\n        self._record(gen_record)\n        return champion, gen_record\n\n    def run(self, generations: int = 5, n_blind: int = 14) -> dict[str, Any]:\n        g = Genome.champion()\n        history = []\n        for i in range(generations):\n            self._say(f"\\n--- generation {i + 1}/{generations}")\n            g, rec = self.generation(g, n_blind=n_blind)\n            history.append(rec)\n        return {"final_version": g.version, "generations": history}\n\n    @staticmethod\n    def _record(rec: dict) -> None:\n        os.makedirs(os.path.dirname(LINEAGE_PATH), exist_ok=True)\n        with open(LINEAGE_PATH, "a") as f:\n            f.write(json.dumps(rec, default=str) + "\\n")\n\n\n_HOLDOUT_REJECTION_RE = re.compile(\n    r"failed sealed holdout: (?P<challenger>-?\\d+\\.\\d+) did not clear champion "\n    r"(?P<champion>-?\\d+\\.\\d+) \\+ margin (?P<margin>\\d+\\.\\d+) "\n    r"\\((?P<draws>\\d+) cumulative draws")\n\n\ndef summarize_holdout_pressure(lineage: list[dict], champion_version: int) -> dict[str, Any]:\n    """Read-only summary of `EvolutionRun.generation()`\'s own lineage records,\n    scoped to whichever generations ran while `champion_version` was reigning.\n\n    Separates two failure modes that both just look like "champion held": a\n    generation where nothing even cleared the fold-aggregate gate\n    (`fold_blocked_generations`), versus one where a real fold-aggregate\n    winner reached the sealed holdout and was rejected only there -- the\n    entrenchment pattern the 2026-08-18 4h-shadow work first named ("a lucky\n    holdout draw at promotion time can entrench a champion against\n    genuinely-better-on-search-folds challengers"). Answers whether the\n    *live* champion shows the pattern using lineage already recorded in\n    `live_state.json` -- no new `evolve` run required.\n\n    `generation()` checks up to 3 top-ranked candidates per generation and\n    holdout-tests every one that clears the fold-aggregate gate (not just the\n    single best), but only the *last* one checked survives into\n    `gen_record["holdout"]` -- the rest are visible only as rejection\n    entries, each carrying its own `fold_fitness` alongside a `why` string in\n    `holdout_accepts()`\'s fixed format. Parsing that format (instead of\n    reading `gen_record["holdout"]` alone) is what recovers every individual\n    holdout draw, not just one representative per generation -- verified by\n    `tests/test_holdout_pressure.py` constructing rejection entries from the\n    real `constitution.holdout_accepts()` output, so a template change there\n    would break the parser loudly rather than silently under-counting draws.\n    """\n    gens = [e for e in lineage if e.get("champion_version") == champion_version]\n    draws = []\n    no_proposal_generations = fold_blocked_generations = accepted_generations = 0\n    for e in gens:\n        if not e.get("n_candidates"):\n            no_proposal_generations += 1\n            continue\n        if e.get("accepted"):\n            accepted_generations += 1\n            continue\n        saw_holdout = False\n        for r in e.get("rejections", []):\n            m = _HOLDOUT_REJECTION_RE.search(r.get("why", ""))\n            if not m:\n                continue\n            saw_holdout = True\n            draws.append({\n                "fold_fitness": r.get("fold_fitness"),\n                "champion_fold_fitness": e.get("champion_fitness"),\n                "holdout_challenger": float(m["challenger"]),\n                "holdout_champion": float(m["champion"]),\n                "margin": float(m["margin"]),\n                "cumulative_draws": int(m["draws"]),\n            })\n        if not saw_holdout:\n            fold_blocked_generations += 1\n    return {\n        "champion_version": champion_version,\n        "n_generations": len(gens),\n        "no_proposal_generations": no_proposal_generations,\n        "fold_blocked_generations": fold_blocked_generations,\n        "accepted_generations": accepted_generations,\n        "holdout_draws": draws,\n    }\n'

_PKGS = ['agents', 'constitution', 'core', 'loop']


def _install():
    import importlib.abc, importlib.machinery

    class _Loader(importlib.abc.Loader):
        def create_module(self, spec):
            m = types.ModuleType(spec.name)
            m.__file__ = spec.name.replace(".", "/") + ".py"
            m.__package__ = spec.name if spec.name in _PKGS else spec.name.rpartition(".")[0]
            if spec.name in _PKGS:
                m.__path__ = []
            return m

        def exec_module(self, module):
            exec(compile(_SRC[module.__name__], module.__file__, "exec"), module.__dict__)

    class _Finder(importlib.abc.MetaPathFinder):
        def find_spec(self, name, path=None, target=None):
            if name in _SRC:
                return importlib.machinery.ModuleSpec(
                    name, _Loader(), is_package=name in _PKGS)
            return None

    sys.meta_path.insert(0, _Finder())


_install()


def _reconstruct_champion_genome(version, lineage):
    """Rebuild a historical champion genome purely from live_state.json's own
    recorded `lineage` (every accepted promotion's patch), by replaying
    accepted patches from the seed forward. There is no persisted genome
    archive to load from directly -- `state/genomes/` is gitignored,
    rebuildable-cache-only (see .gitignore) -- so this is the only way to get
    at a specific past champion's actual genes for a comparison diagnostic.
    Used by `fold-scheme --also-version N`. Raises ValueError if `version`
    was never an accepted promotion recorded in lineage (version 1, the
    seed, always succeeds and needs no patches)."""
    from core.genome import Genome

    patches_by_version = {}
    for e in lineage:
        acc = e.get("accepted")
        if acc:
            patches_by_version[acc["new_version"]] = acc["patch"]

    g = Genome.champion()
    versions = {1: g}
    for v in sorted(patches_by_version):
        g = g.child(list(patches_by_version[v].items()), note=f"reconstructed-v{v}")
        versions[v] = g

    if version not in versions:
        raise ValueError(
            f"genome version {version} has no accepted promotion recorded in "
            f"lineage (known versions: {sorted(versions)})"
        )
    return versions[version]


def _adversarial_concentration_genome(base):
    """Build a genome deliberately mutated to concentrate exposure -- the
    last open check on AGENTS.md item 3's correlation question. Every real
    champion measured so far (v1, v2, v3, via `correlation-universe
    --realized --also-version N`) landed on a held-set that's *less*
    correlated than the universe average, purely as a side effect of normal
    entry/exit tuning -- nothing in the genome rewards diversification.
    This asks the sharper question `--also-version` can't: can a genome
    that never rewards diversification (the correlation_penalty gene this
    question was about has since been removed as dead weight -- see
    AGENTS.md item 3) look concentrated anyway, once it stops being
    selective at all? Every entry gate across all three
    consults is loosened to near pass-through -- the rank/trend/RSI/vol
    filters that normally stagger entries across symbols and time are
    disabled -- and every position-count/cash-floor limit is raised so the
    council can act on all of that permissiveness inside a single bar
    instead of trickling positions in one at a time. Built from `base` (the
    live champion) via the same `Genome.child()` patch mechanism every real
    promotion uses, but never run through evolution, never scored against a
    holdout, never promoted -- a single hand-built genome, used only to
    measure its own held-set correlation. Never touches live_state.json."""
    patches = [
        ("agents.consult_risky.genes.min_rank_mom", 0.0),
        ("agents.consult_risky.genes.min_breakout", -0.30),
        ("agents.consult_risky.genes.min_slope", -1.0),
        ("agents.consult_risky.genes.rsi_max", 100.0),
        ("agents.consult_moderate.genes.min_trend", -0.10),
        ("agents.consult_moderate.genes.rsi_lo", 5.0),
        ("agents.consult_moderate.genes.rsi_hi", 95.0),
        ("agents.consult_moderate.genes.min_rank_mom", 0.0),
        ("agents.consult_moderate.genes.max_vol", 10.0),
        ("agents.consult_conservative.genes.rsi_buy_below", 90.0),
        ("agents.consult_conservative.genes.z_buy_below", 5.0),
        ("agents.consult_conservative.genes.require_uptrend", False),
        ("agents.consult_conservative.genes.min_trend", -1.0),
        ("agents.consult_conservative.genes.max_vol", 10.0),
        ("agents.risk_judge.genes.min_conviction", 0.0),
        ("agents.risk_judge.genes.max_positions", 20),
        ("agents.risk_judge.genes.cash_floor_pct", 0.0),
        ("agents.superior_judge.genes.hard_max_positions", 20),
        ("agents.superior_judge.genes.max_new_positions_per_bar", 15),
        ("agents.superior_judge.genes.hard_cash_floor_pct", 0.0),
        ("risk.max_bars_held", 90),
    ]
    return base.child(patches, note="adversarial-concentration (diagnostic only, never promoted)")


def _adversarial_concentration_genome_tight(base):
    """The narrower adversarial construction AGENTS.md item 3 still flagged
    as open after `_adversarial_concentration_genome` above: that genome
    concentrated by *losing selectivity* (near-pass-through entry gates) --
    and it also crossed `MAX_DD_HARD_FAIL`, so it never would have cleared a
    real search's acceptance gate. That leaves untested whether a genome can
    concentrate *without* failing the other gates: selectivity untouched
    (every consult entry gate stays exactly as evolution tuned it -- nothing
    here is patched), no diversification requirement (this genome predates
    `correlation_penalty`'s removal -- see AGENTS.md item 3 -- and never
    used it anyway), but forced into fewer, larger simultaneous positions
    instead of the champion's normal 6 slots. If concentration only ever
    showed up when the drawdown gate was already about to fail, that would
    have been the first case for keeping `correlation_penalty` as a live
    safety valve rather than dropping it -- it wasn't, and the gene is gone.
    3 slots, not fewer: `loop.engine.pairwise_correlation_stats` needs at
    least 3 simultaneously-held symbols to report anything at all, so a
    2-slot cap (tried first) produced maxDD/fitness numbers but zero
    held-only correlation rows -- unmeasurable by construction, not a
    result. Built the same way as `_adversarial_concentration_genome` --
    `Genome.child()` patches over `base` (the live champion), never run
    through evolution, never scored against a holdout, never promoted, used
    only to measure its own held-set correlation. Never touches
    live_state.json."""
    patches = [
        ("agents.risk_judge.genes.max_positions", 3),
        ("agents.risk_judge.genes.max_position_pct", 0.9),
        ("agents.risk_judge.genes.cash_floor_pct", 0.05),
        ("agents.superior_judge.genes.hard_max_positions", 3),
        ("agents.superior_judge.genes.hard_max_position_pct", 0.9),
        ("agents.superior_judge.genes.hard_cash_floor_pct", 0.02),
    ]
    return base.child(patches, note="adversarial-concentration-tight (diagnostic only, never promoted)")


def main():
    cmd = sys.argv[1] if len(sys.argv) > 1 else "tick"
    import constitution
    from constitution import verify
    from core.live import LiveAccount

    # bundled mode: hash the embedded source, since there are no files on disk
    constitution.EMBEDDED_SOURCES.update(
        {k: _SRC[k] for k in ("constitution", "core.portfolio")})

    state_path = os.environ.get("EVO_STATE", "live_state.json")
    ok, msg = verify(os.environ.get("EVO_MANIFEST", "evotrader.manifest"))
    print(f"[constitution] {msg}")
    if not ok:
        sys.exit(1)

    acct = LiveAccount.load(state_path)
    if cmd == "tick":
        entry = acct.tick(force="--force" in sys.argv)
        if "error" in entry:
            print(f"[live] error: {entry['error']}")
            sys.exit(1)
        if "skipped" in entry:
            print(f"[live] {entry['skipped']} — nothing to do")
            return
        acct.save(state_path)
        print(json.dumps({k: v for k, v in entry.items() if k != "decision"}, indent=2))
        d = entry.get("decision") or {}
        for f in (d.get("fills") or []):
            print(f"  {f['status']:8s} {f['side']:4s} {f['symbol']:10s} {f.get('reason','')[:110]}")
        if not (d.get("fills")):
            print("  no trades this bar")
    elif cmd == "signals":
        print(acct.signals())
    elif cmd == "summary":
        print(json.dumps(acct.summary(), indent=2, default=str))
    elif cmd == "evolve":
        # Self-improvement runs against the same durable state: the champion
        # genome lives inside live_state.json, so a promotion made today is
        # what trades tomorrow.
        from core import market
        from core.genome import Genome
        from loop.evolve import EvolutionRun
        n = int(sys.argv[2]) if len(sys.argv) > 2 else 3
        g0 = acct.genome
        g0.save("champion")
        data = market.load_universe(g0.universe, g0.bar_interval, 4.0)
        print(f"[evolve] {len(data)} symbols, champion v{g0.version} "
              f"({g0.bar_interval} bars), {n} generations")
        # Resume the Researcher's memory of already-rejected proposals from the
        # last evolve invocation against this same champion, instead of starting
        # blind every time a new process runs. Without this, the multiple-testing
        # bar (which is *supposed* to keep rising the longer a champion survives)
        # was silently resetting to n=1 at the start of every separate `evolve`
        # call, and known losers (e.g. regime_scale.bear) got re-tested for free
        # across sessions instead of staying excluded.
        mem = acct.researcher_memory or {}
        if mem.get("champion_version") == g0.version:
            init_tested = {tuple(tuple(pair) for pair in item) for item in mem.get("tested", [])}
            init_stagnation = int(mem.get("stagnation", 0))
        else:
            init_tested, init_stagnation = set(), 0
        # Holdout draws are seeded unconditionally, NOT keyed to the champion.
        # The rejected-proposal set is per-champion because a patch refused
        # against v1 may be right for v2; the holdout is the same slice of
        # history either way, so its exposure accumulates across the lineage.
        init_holdout_draws = int(mem.get("holdout_draws", 0))
        run = EvolutionRun(data, seed=None, initial_tested=init_tested,
                           initial_stagnation=init_stagnation,
                           initial_champion_version=g0.version,
                           initial_holdout_draws=init_holdout_draws)
        res = run.run(generations=n, n_blind=14)
        acct.lineage.extend(res.get("generations", []))
        acct.researcher_memory = {
            "champion_version": run.tested_version,
            "tested": [[list(pair) for pair in k] for k in run.tested],
            "stagnation": run.stagnation,
            "holdout_draws": run.holdout_draws,
        }
        final = Genome.champion()
        if final.version != g0.version:
            acct.genome = final          # tomorrow's trading uses the new roster
            acct.save(state_path)
            print(f"[evolve] champion promoted to v{final.version}")
        else:
            acct.save(state_path)
            print("[evolve] champion held")
    elif cmd in ("anatomy", "consults"):
        # Diagnostics. Neither touches live_state.json or the champion: they
        # replay history and report on it. Slow (a full backtest) and meant to
        # be read by a human, not by the evolution loop.
        from core import market
        from loop.engine import consult_correlation, run_backtest, trade_anatomy
        g0 = acct.genome
        data = market.load_universe(g0.universe, g0.bar_interval, 4.0)
        if not data:
            print("no market data")
            sys.exit(1)
        print(f"[{cmd}] replaying {len(data)} symbols against champion "
              f"v{g0.version} ({g0.bar_interval} bars) ...", flush=True)
        res = run_backtest(g0, data, 0.0, 1.0, log_detail=True)
        if "error" in res:
            print(f"backtest failed: {res['error']}")
            sys.exit(1)

        def _money(x):
            return f"${x:,.0f}"

        if cmd == "anatomy":
            a = trade_anatomy(res)
            if "error" in a:
                print(a["error"])
                sys.exit(1)
            st, bench = res.get("stats", {}), res.get("benchmark", {})
            edge = res.get("edge", {})
            print()
            print(f"TRADE ANATOMY — champion v{g0.version}, "
                  f"{res['window']['start'][:10]} to {res['window']['end'][:10]}")
            print("=" * 72)
            print(f"  {a['n_trades']} closed trades | win rate {a['win_rate']:.1%} | "
                  f"profit factor {a['profit_factor']:.2f}")
            print(f"  expectancy per trade {_money(a['expectancy'])} | "
                  f"total {_money(a['total_pnl'])}")
            print(f"  median win {_money(a['median_win'])} vs "
                  f"median loss {_money(a['median_loss'])}   "
                  f"(mean {_money(a['mean_win'])} / {_money(a['mean_loss'])})")
            print(f"  top 5 losses are {a['top_loss_share_of_gross_loss']:.0%} "
                  f"of all losses")
            if bench:
                print(f"  strategy {st.get('total_return', 0):+.1%} vs "
                      f"buy-and-hold {bench.get('total_return', 0):+.1%}  "
                      f"-> excess {edge.get('excess_return', 0):+.1%}")
            for title, key in (("BY ENTRY AGENT", "by_entry_agent"),
                               ("BY EXIT MECHANISM", "by_exit_reason"),
                               ("BY MARKET REGIME", "by_regime"),
                               ("BY HOLDING PERIOD", "by_holding_period")):
                print()
                print(f"  {title}")
                for k, g in a[key].items():
                    print(f"    {k[:34]:<34s} {_money(g['pnl']):>12s}  "
                          f"n={g['n']:<5d} win {g['win_rate']:.0%}")
            print()
            print("  WORST 5 TRADES")
            for t in a["largest_losses"]:
                print(f"    {t['symbol']:<10s} {_money(t['pnl']):>10s}  "
                      f"{t['pnl_pct']:+7.1%}  {t['bars_held']:>3}d  "
                      f"{t['entry_ts']}  {t['exit_reason']}")
            print()
            print("  BEST 5 TRADES")
            for t in a["largest_wins"]:
                print(f"    {t['symbol']:<10s} {_money(t['pnl']):>10s}  "
                      f"{t['pnl_pct']:+7.1%}  {t['bars_held']:>3}d  "
                      f"{t['entry_ts']}  {t['exit_reason']}")
            print()
            print("  Worst symbols: " + ", ".join(
                f"{k} {_money(v['pnl'])}" for k, v in list(a["by_symbol"].items())[:5]))
        else:
            c = consult_correlation(res)
            if "error" in c:
                print(c["error"])
                sys.exit(1)
            print()
            print(f"CONSULT INDEPENDENCE — champion v{g0.version}")
            print("=" * 72)
            print(f"  {c['n_active_bars']} logged bars, "
                  f"{c['n_proposal_points']} proposal points")
            print(f"  note: {c['note']}")
            print()
            print("  PAIRWISE")
            for pair, v in c["pairs"].items():
                sc = v["signal_correlation"]
                ss = v["same_side_when_both_act"]
                print(f"    {pair}")
                print(f"      signal correlation   "
                      f"{'n/a' if sc is None else format(sc, '+.3f')}")
                print(f"      proposal overlap     "
                      f"{v['proposal_overlap_jaccard']:.1%} "
                      f"({v['n_shared_proposals']} shared)")
                print(f"      same side when both  "
                      f"{'n/a' if ss is None else format(ss, '.1%')}")
            if c["by_regime"]:
                print()
                print("  SIGNAL CORRELATION BY REGIME")
                for r, d in c["by_regime"].items():
                    inner = "  ".join(
                        f"{k}={'n/a' if v is None else format(v, '+.2f')}"
                        for k, v in d.items())
                    print(f"    {r:<8s} {inner}")
            print()
            print(f"  trades credited to more than one consult: "
                  f"{c['trades_with_multiple_entry_agents']:.1%}")
            print()
            print("  Reading it: correlations near +1 mean the consults are one "
                  "opinion wearing\n  three hats, and their agreement carries no "
                  "extra information for the Risk Judge.")
    elif cmd == "costs":
        # Diagnostic: how sensitive is the champion to the fee/slippage
        # assumptions baked into its own genome? Never touches live_state.json
        # or the champion — replays history at scaled cost multipliers and
        # reports the drag. Slow (one full backtest per scenario), meant for a
        # human to read.
        #
        # --holdout: replay only the sealed HOLDOUT_FRAC slice (the newest
        # bars, never touched during search) instead of the full history.
        # Full-history numbers average over years the champion was tuned
        # against; the holdout is the honest out-of-sample check, and
        # AGENTS.md flagged after the first `costs` run that its maxDD margin
        # to the hard-fail gate looked thinner than the full-history numbers
        # suggested — this answers that directly instead of inferring it.
        import copy
        from constitution import HOLDOUT_FRAC
        from core import market
        from core.genome import Genome
        from loop.engine import run_backtest
        use_holdout = "--holdout" in sys.argv
        g0 = acct.genome
        data = market.load_universe(g0.universe, g0.bar_interval, 4.0)
        if not data:
            print("no market data")
            sys.exit(1)
        start_frac, end_frac = (1.0 - HOLDOUT_FRAC, 1.0) if use_holdout else (0.0, 1.0)
        base_fee = float(g0.data["broker"]["fee_bps"])
        base_slip = float(g0.data["broker"]["slippage_bps"])
        scenarios = [
            ("baseline", 1.0, 1.0),
            ("1.5x costs", 1.5, 1.5),
            ("2x costs", 2.0, 2.0),
            ("3x costs", 3.0, 3.0),
            ("slippage stress (5x)", 1.0, 5.0),
        ]
        window_desc = (f"sealed holdout (newest {HOLDOUT_FRAC:.0%} of history)"
                       if use_holdout else "full history")
        print(f"[costs] replaying {len(data)} symbols against champion v{g0.version} "
              f"({g0.bar_interval} bars) over the {window_desc} at {len(scenarios)} "
              f"cost scenarios (baseline fee {base_fee:.1f}bps / "
              f"slippage {base_slip:.1f}bps) ...", flush=True)
        rows = []
        for label, fee_mult, slip_mult in scenarios:
            d = copy.deepcopy(g0.data)
            d["broker"]["fee_bps"] = base_fee * fee_mult
            d["broker"]["slippage_bps"] = base_slip * slip_mult
            g = Genome(d)
            res = run_backtest(g, data, start_frac, end_frac, log_detail=False)
            if "error" in res:
                print(f"  {label}: backtest failed: {res['error']}")
                continue
            st, edge = res.get("stats", {}), res.get("edge", {})
            rows.append((label, fee_mult, slip_mult, st, edge, res.get("fitness")))
            print(f"  ... {label} done", flush=True)
        print()
        print(f"COST SENSITIVITY — champion v{g0.version} — {window_desc}")
        print("=" * 96)
        print(f"  {'scenario':<22s} {'fitness':>8s} {'return':>9s} {'sharpe':>7s} "
              f"{'maxDD':>7s} {'trades':>7s} {'fees paid':>11s} {'excess ret':>11s}")
        for label, fee_mult, slip_mult, st, edge, fit in rows:
            print(f"  {label:<22s} {fit:>8.3f} {st.get('total_return', 0):>8.1%} "
                  f"{st.get('sharpe', 0):>7.2f} {st.get('max_dd', 0):>7.1%} "
                  f"{st.get('trades', 0):>7d} ${st.get('fees_paid', 0):>9,.0f} "
                  f"{edge.get('excess_return', 0):>10.1%}")
        if rows:
            base = rows[0]
            worst = min(rows, key=lambda r: r[5])
            print()
            print(f"  baseline fitness {base[5]:.3f} -> worst scenario "
                  f"'{worst[0]}' fitness {worst[5]:.3f} "
                  f"({worst[5] - base[5]:+.3f})")
    elif cmd == "regime":
        # Diagnostic: what does each walk-forward fold and the sealed holdout
        # actually look like as a *market*, independent of any genome or
        # backtest? Never touches live_state.json or the champion — just
        # slices the same windows Evaluator.folds()/HOLDOUT_FRAC use and
        # reports buy-and-hold behaviour over each one. Exists because the
        # 2026-08-17 4h shadow runs found every accepted promotion's
        # fold-aggregate fitness staying negative while its holdout fitness
        # was strongly positive and rising -- this answers "what's actually
        # different about the two windows" directly instead of inferring it
        # from fitness numbers alone. `--interval` overrides the champion's
        # own bar_interval, so this can be pointed at a bar size nothing live
        # trades on yet.
        from constitution import HOLDOUT_FRAC, N_FOLDS
        from core import market
        from core.market import Replay
        from loop.engine import benchmark_buy_hold
        interval = None
        if "--interval" in sys.argv:
            interval = sys.argv[sys.argv.index("--interval") + 1]
        g0 = acct.genome
        interval = interval or g0.bar_interval
        data = market.load_universe(g0.universe, interval, 4.0)
        if not data:
            print("no market data")
            sys.exit(1)
        replay = Replay({s: df for s, df in data.items() if s in g0.universe})
        n = len(replay)
        search_end = 1.0 - HOLDOUT_FRAC
        edges = [i / N_FOLDS * search_end for i in range(N_FOLDS + 1)]
        windows = [(f"fold {i + 1}", edges[i], edges[i + 1]) for i in range(N_FOLDS)]
        windows.append(("holdout", search_end, 1.0))
        bcfg = g0.data.get("broker", {})
        cash = float(bcfg.get("start_cash", 10_000.0))
        bpy = market.BARS_PER_YEAR.get(interval, 365.25)
